/* Spanish translation of the CompTIA Server+ practice questions. Options keep the same order as the English bank. */
CertHub.addQuestionsEs("server-plus", {
  "sv1": ["Un administrador está llenando un rack vacío de 42U con un UPS, un arreglo de almacenamiento y varios servidores de 1U. ¿Dónde debe ir el UPS?", ["En la parte superior, cerca del techo, para mejor enfriamiento", "En el medio, a la altura de los ojos para leerlo fácilmente", "En un rack separado junto a los servidores", "En la parte inferior del rack"], "Los equipos pesados como los UPS van en la parte inferior para mantener bajo el centro de gravedad del rack. Montarlos arriba hace que el rack quede pesado en la parte superior y sea riesgoso cuando se deslizan los servidores hacia afuera.", ["Montar un UPS pesado en lo alto hace que el rack quede pesado arriba y propenso a volcarse; la altura no mejora el enfriamiento.", "Colocarlo a la altura de los ojos es una comodidad, no una regla de seguridad, y aun así eleva el centro de gravedad del rack.", "Un UPS va en la parte inferior del mismo rack; ponerlo en un rack aparte desperdicia espacio y es innecesario.", null]],
  "sv2": ["Un data center usa un diseño de pasillo caliente/pasillo frío. ¿Hacia dónde deben instalarse los servidores?", ["Con el frente hacia el pasillo caliente para que el aire de escape se enfríe", "Con el frente hacia el pasillo frío para que la toma aspire aire frío", "En direcciones alternas en cada rack", "De lado, para que el aire circule libremente entre racks y filas vecinas"], "Los servidores aspiran aire frío por el frente y expulsan por la parte trasera, así que el frente debe mirar al pasillo frío. Orientarlos hacia el pasillo caliente haría que aspiren el aire de escape.", ["Orientar el frente hacia el pasillo caliente hace que las tomas aspiren aire caliente de escape y los servidores se sobrecalienten.", null, "Alternar la dirección de los racks mezcla el escape caliente con la toma de aire frío y anula la separación de pasillos.", "Montar los servidores de lado rompe el diseño de flujo de aire de los pasillos y hace que el escape recircule hacia las tomas."]],
  "sv3": ["Un servidor tiene dos fuentes de poder. Para eliminar puntos únicos de falla en la ruta de energía, ¿cómo deben conectarse?", ["Cada una a un PDU distinto alimentado por un circuito distinto", "Ambas al mismo PDU en un solo UPS", "Una a un PDU y otra a un tomacorriente de pared", "Ambas a una regleta con protección contra sobretensiones conectada a un solo UPS"], "PDU separados en circuitos separados (alimentaciones A y B) significan que la falla de un PDU, UPS o breaker no tumba el servidor.", [null, "Un solo PDU en un solo UPS es en sí mismo un punto único de falla, así que una falla ahí igual apaga el servidor.", "Un tomacorriente de pared no está acondicionado ni protegido, y mezclarlo con un PDU deja una ruta de energía desbalanceada.", "Una regleta y un solo UPS son puntos únicos de falla que alimentan ambas fuentes a la vez."]],
  "sv4": ["Seis discos de 4 TB se configuran como RAID 6. ¿Cuál es la capacidad utilizable?", ["24 TB", "20 TB", "16 TB", "12 TB"], "RAID 6 usa la capacidad de dos discos para la paridad doble: (6 − 2) × 4 TB = 16 TB. RAID 5 daría 20 TB.", ["24 TB es el total bruto (o RAID 0) e ignora la capacidad que consume la paridad doble.", "20 TB es el resultado de RAID 5, que reserva solo un disco de paridad, no los dos que usa RAID 6.", null, "12 TB resta la capacidad de tres discos; RAID 6 solo reserva dos para su paridad doble."]],
  "sv5": ["Un servidor de base de datos necesita el mejor rendimiento de escritura y debe sobrevivir a la falla de un disco. El tiempo de reconstrucción debe ser corto. ¿Qué nivel de RAID es adecuado?", ["RAID 10", "RAID 5", "RAID 0", "RAID 6 con un hot spare"], "RAID 10 hace striping sobre espejos, así que las escrituras no tienen penalización de paridad y las reconstrucciones solo copian un espejo. RAID 5 y 6 agregan penalizaciones de escritura por paridad y reconstrucciones largas.", [null, "RAID 5 agrega una penalización de escritura por paridad y reconstruye lentamente recalculando la paridad en todos los discos.", "RAID 0 no tiene ninguna redundancia, así que la falla de un solo disco destruye todo el arreglo.", "La paridad doble de RAID 6 ralentiza aún más las escrituras y sus reconstrucciones son largas, incluso con un hot spare disponible."]],
  "sv6": ["¿Qué opción de almacenamiento presenta LUN a nivel de bloque a los servidores sobre una red Ethernet estándar?", ["NAS usando SMB", "SAN iSCSI", "DAS sobre SAS", "Export NFS"], "iSCSI transporta comandos SCSI de bloque sobre TCP/IP, así que los servidores ven los LUN como discos locales. Los protocolos NAS como SMB y NFS comparten archivos, no bloques.", ["NAS con SMB comparte datos a nivel de archivo por la red, no como LUN a nivel de bloque.", null, "DAS sobre SAS es almacenamiento de bloque, pero está conectado directamente a un servidor, no se entrega por Ethernet.", "NFS es un recurso compartido de red a nivel de archivo, así que los servidores ven carpetas montadas en lugar de LUN de bloque."]],
  "sv7": ["Un administrador debe reemplazar un disco fallado en un servidor de producción sin apagarlo. ¿Qué característica deben soportar la bahía del disco y la controladora?", ["Caché write-back", "Secure Boot", "Hot-swap", "Wake-on-LAN"], "Las bahías hot-swap permiten retirar y reemplazar un disco mientras el sistema está en funcionamiento. La caché write-back mejora el rendimiento, pero no permite el reemplazo en caliente.", ["La caché write-back mejora el rendimiento de escritura, pero no permite reemplazar un disco con el equipo encendido.", "Secure Boot verifica componentes de arranque firmados y no tiene relación con el reemplazo de discos en caliente.", null, "Wake-on-LAN enciende un sistema de forma remota y no tiene nada que ver con el hot-swap de discos."]],
  "sv8": ["Un disco nuevo de 8 TB aparece como aproximadamente 7.28 TB en el sistema operativo. ¿Qué explica la diferencia?", ["Espacio reservado para la controladora RAID", "Un disco que está fallando con sectores dañados", "El journal del sistema de archivos", "El cálculo de capacidad en base 10 frente a base 2"], "Los fabricantes cuentan 1 TB como 10^12 bytes; el sistema operativo reporta en unidades de 2^40 bytes. 8 × 10^12 / 2^40 ≈ 7.28.", ["No se menciona RAID, y las controladoras no reservan suficiente espacio para explicar la diferencia.", "La cifra menor es matemática normal de reporte, no un síntoma de un disco con sectores dañados.", "El journal de un sistema de archivos es muy pequeño y no puede explicar cientos de gigabytes de diferencia aparente.", null]],
  "sv9": ["Un servidor remoto se colgó y el sistema operativo no responde por la red. ¿Qué herramienta permite al administrador reiniciarlo apagándolo y encendiéndolo y ver el POST de forma remota?", ["RDP", "El BMC, como iDRAC o iLO", "SSH", "Traps SNMP enviados a la consola de monitoreo"], "Un baseboard management controller funciona de forma independiente del sistema operativo en su propio puerto de red y ofrece control de energía y consola remotos. RDP y SSH necesitan un sistema operativo funcionando.", ["RDP depende de un sistema operativo y una pila de red en funcionamiento, así que no sirve cuando el sistema operativo no responde.", null, "SSH también necesita un sistema operativo y un servicio funcionando, que es justamente lo que falló aquí.", "Los traps SNMP solo envían mensajes de alerta; no pueden reiniciar el hardware ni mostrar la pantalla del POST."]],
  "sv10": ["¿Qué configuración debe habilitarse en UEFI para asegurar que solo se carguen bootloaders y kernels de sistema operativo firmados?", ["Secure Boot", "Legacy boot", "PXE boot", "Fast boot"], "Secure Boot verifica las firmas de los componentes de arranque contra claves de confianza. El arranque Legacy (CSM) desactiva esa verificación.", [null, "El arranque Legacy (CSM) desactiva la verificación de firmas, que es lo contrario de lo que se busca.", "PXE boot carga un sistema operativo o instalador por la red y no exige bootloaders firmados.", "Fast boot omite partes del arranque para ganar velocidad y no valida las firmas de los componentes de arranque."]],
  "sv11": ["Un administrador necesita conectar dos switches top-of-rack con un enlace de 10 Gbps corto y de bajo costo. ¿Qué opción es la MEJOR?", ["Fibra monomodo con ópticas LR", "Un cable patch Cat5e largo tendido por la bandeja superior", "Cable Twinax de cobre de conexión directa (DAC)", "Cable coaxial RG-6"], "Un DAC pasivo es económico e ideal para tramos cortos de 10 Gbps entre puertos SFP+. Las ópticas LR funcionan, pero cuestan mucho más para unos pocos metros.", ["La fibra monomodo con ópticas LR funciona, pero cuesta mucho más de lo necesario para un enlace de pocos metros.", "Cat5e no está certificado para 10 Gbps confiables y es una mala opción para una interconexión corta y rápida entre switches.", null, "El coaxial RG-6 es para señales de video/CATV y no puede transportar un enlace SFP+ de 10 Gbps entre switches."]],
  "sv12": ["Antes de actualizar el firmware de un servidor, ¿qué debe hacer PRIMERO el administrador?", ["Desactivar el firewall del host", "Restablecer el BIOS a los valores predeterminados", "Retirar las fuentes de poder redundantes para evitar una sobretensión durante el flasheo", "Revisar las notas de la versión y la compatibilidad, y tener un plan de reversión"], "Las actualizaciones de firmware pueden romper drivers o el soporte de hardware, así que hay que revisar las notas, probar y planificar la reversión en una ventana de mantenimiento. Restablecer el BIOS a sus valores predeterminados puede deshacer configuraciones necesarias.", ["Desactivar el firewall del host no tiene relación con el flasheo del firmware y solo debilita la seguridad.", "Restablecer el BIOS a sus valores predeterminados borraría configuraciones necesarias en lugar de preparar la actualización.", "Retirar fuentes de poder arriesga perder energía a mitad del flasheo, lo que puede dejar inservible el firmware.", null]],
  "sv13": ["Un servidor necesita memoria que pueda detectar y corregir errores de un solo bit. ¿Qué se debe pedir?", ["DIMM de escritorio sin paridad", "Memoria ECC", "DIMM unbuffered de mayor frecuencia", "Más espacio de swap en SSD"], "La memoria con código de corrección de errores (ECC) detecta y corrige errores de un solo bit, lo cual es estándar en servidores. Una memoria más rápida sin ECC no ofrece corrección.", ["Los DIMM de escritorio sin paridad no pueden detectar ni corregir errores de memoria.", null, "La memoria unbuffered más rápida sin ECC ofrece velocidad, pero no la corrección de errores que necesitan los servidores.", "Agregar swap en SSD es paginación en disco y no corrige errores de bits en memoria."]],
  "sv14": ["Una oficina pequeña no tiene espacio para racks y necesita un servidor independiente y silencioso debajo de un escritorio. ¿Qué factor de forma es adecuado?", ["Blade", "Rack de 2U", "Torre", "Rack de 1U"], "Los servidores torre son independientes y más silenciosos, ideales para oficinas sin racks. Los blades necesitan un chasis y los servidores de rack necesitan rieles y un rack.", ["Un servidor blade requiere un chasis y un rack, que esta oficina no tiene.", "Un servidor de rack de 2U igual necesita un rack y un kit de rieles para instalarse.", null, "Un servidor de rack de 1U necesita un rack y sus ventiladores pequeños de alta velocidad son ruidosos para una oficina."]],
  "sv15": ["Un administrador necesita saber cuánto tiempo un UPS mantendrá funcionando el rack durante un corte. ¿Qué dos valores son los MÁS importantes?", ["La capacidad de la batería y la carga total en watts", "La altura del rack y el número de servidores", "El voltaje de entrada, el tipo de tomacorriente y la altura física del rack", "La velocidad de CPU y la RAM de los servidores"], "La autonomía depende de cuánta energía almacenan las baterías y cuánta potencia consume la carga. Los tipos de tomacorriente importan para la conexión, no para la autonomía.", [null, "La altura del rack y la cantidad de servidores describen el tamaño físico, no cuánto tiempo pueden sostener la carga las baterías.", "El voltaje y el tipo de tomacorriente importan para la conexión, y la altura física no influye en el cálculo de energía de la autonomía.", "La velocidad de CPU y la RAM no dan directamente el consumo en watts necesario para calcular la autonomía."]],
  "sv16": ["¿Qué interfaz de disco ofrece la menor latencia al conectar el almacenamiento flash directamente mediante líneas PCIe?", ["SATA", "SAS", "USB 3", "NVMe"], "NVMe fue diseñado para flash y usa PCIe directamente, evitando las capas de controladora SATA/SAS. SAS es de nivel empresarial, pero sigue siendo más lento que NVMe.", ["SATA es una interfaz AHCI más antigua con mayor latencia que una conexión flash directa por PCIe.", "SAS es de nivel empresarial, pero sigue pasando por una capa de controladora, lo que lo hace más lento que NVMe.", "USB 3 es un bus externo de periféricos, no una ruta interna de almacenamiento de baja latencia.", null]],
  "sv17": ["Un administrador debe instalar la misma imagen de sistema operativo en 40 servidores nuevos por la red, sin medios físicos. ¿Qué método es adecuado?", ["Instalar desde USB en cada uno", "Arranque PXE hacia un servidor de despliegue", "Clonar con un hipervisor Tipo 2", "Usar una conversión P2V desde un servidor de referencia"], "PXE permite que los servidores arranquen desde la red y descarguen una imagen o una instalación desatendida desde un servidor de despliegue. Las instalaciones por USB no escalan a 40 servidores.", ["Instalar desde USB en cada uno de 40 servidores es manual y no escala.", null, "Un hipervisor Tipo 2 corre sobre un sistema operativo de escritorio y no es una herramienta para despliegue masivo en bare metal.", "P2V convierte un servidor físico existente en una VM; no despliega un sistema operativo en 40 máquinas nuevas."]],
  "sv18": ["Antes de comprar servidores nuevos para un sistema operativo, ¿qué debe revisar el administrador para confirmar que el hardware es compatible?", ["El SLA", "Los términos del acuerdo de licencia de usuario final del sistema operativo", "La lista de compatibilidad de hardware", "El inventario de activos"], "La HCL enumera el hardware que el fabricante del sistema operativo ha probado y soporta. La licencia cubre los derechos de uso, no el soporte de hardware.", ["Un SLA define compromisos de servicio y no dice nada sobre qué hardware soporta el sistema operativo.", "La EULA cubre los derechos de uso, no si el fabricante del sistema operativo probó el hardware.", null, "El inventario de activos lista el equipo que se posee, no la compatibilidad probada por el fabricante para un sistema operativo nuevo."]],
  "sv19": ["Una empresa quiere reducir la superficie de ataque y el uso de recursos de sus servidores de archivos Windows administrados de forma remota. ¿Qué opción de instalación es adecuada?", ["Server Core", "Desktop Experience", "Un hipervisor Tipo 2", "Una edición de 32 bits"], "Server Core no tiene interfaz gráfica completa, así que usa menos recursos y tiene menos componentes que parchear. Desktop Experience agrega la interfaz gráfica y su superficie de ataque.", [null, "Desktop Experience agrega la interfaz gráfica completa, lo que aumenta tanto el uso de recursos como la superficie de ataque.", "Un hipervisor Tipo 2 es un producto de virtualización, no una opción de instalación de Windows Server.", "Una edición de 32 bits limita la memoria y no es la forma de reducir la superficie de ataque; además, Windows Server es de 64 bits."]],
  "sv20": ["Un servidor físico heredado debe trasladarse a un hipervisor con el mínimo trabajo de reconstrucción. ¿Qué proceso se usa?", ["V2P", "Instalación PXE", "Restauración bare-metal", "P2V"], "La conversión de físico a virtual (P2V) copia los discos y la configuración del servidor en funcionamiento a una VM. V2P es la dirección contraria.", ["V2P es el proceso inverso: convierte una máquina virtual de vuelta a hardware físico.", "Una instalación PXE construye un sistema operativo nuevo por la red, lo que implicaría reconstruir, no migrar.", "Una restauración bare-metal recupera un respaldo sobre hardware; no convierte el servidor en una VM.", null]],
  "sv21": ["Un servidor de archivos Linux necesita un sistema de archivos que maneje bien archivos y volúmenes muy grandes y que sea el predeterminado en RHEL. ¿Cuál es adecuado?", ["FAT32", "exFAT", "XFS", "NTFS"], "XFS es el sistema de archivos predeterminado de RHEL y escala a archivos y volúmenes grandes. FAT32 limita los archivos a 4 GB.", ["FAT32 limita cada archivo a 4 GB y no es adecuado para volúmenes grandes de servidor.", "exFAT está orientado a medios flash removibles, no a grandes servidores de archivos Linux empresariales.", null, "NTFS es el sistema de archivos de Windows y no es el predeterminado en RHEL."]],
  "sv22": ["Las dos NIC de un servidor se combinan para que el tráfico continúe si falla un enlace o un puerto del switch. ¿Cómo se llama esto?", ["Etiquetado de VLAN", "NIC teaming", "Port mirroring", "Jumbo frames"], "NIC teaming (bonding) agrupa adaptadores para failover y, a menudo, balanceo de carga. Port mirroring copia el tráfico para análisis.", ["El etiquetado de VLAN segmenta el tráfico en LAN virtuales; no proporciona failover de enlaces.", null, "Port mirroring copia el tráfico a un puerto de monitoreo y no ofrece redundancia.", "Jumbo frames aumentan el MTU para mejorar el rendimiento y no hacen nada por el failover de enlaces."]],
  "sv23": ["Un nuevo controlador de dominio reporta constantemente fallas de autenticación Kerberos, y su reloj está desfasado 12 minutos. ¿Qué servicio debe configurarse?", ["DHCP", "SNMP", "SMTP", "NTP"], "Kerberos solo tolera un pequeño desfase de reloj (5 minutos por defecto), así que los servidores deben sincronizar la hora con NTP. SNMP es para monitoreo.", ["DHCP asigna direcciones IP y no tiene ningún papel en la sincronización del reloj del servidor.", "SNMP es para monitorear dispositivos, no para mantener la hora sincronizada para Kerberos.", "SMTP transporta correo electrónico y no tiene relación con el desfase de reloj ni con la autenticación.", null]],
  "sv24": ["Un servidor de impresión necesita siempre la misma dirección IP, pero el administrador quiere gestionarla desde el servidor DHCP. ¿Qué se debe crear?", ["Una reserva DHCP", "Una exclusión DHCP", "Un nuevo ámbito (scope)", "Un registro DNS CNAME"], "Una reserva vincula una dirección IP con la MAC del dispositivo para que siempre reciba la misma concesión. Una exclusión solo quita direcciones del pool.", [null, "Una exclusión quita direcciones del pool, pero no asigna una dirección fija a un dispositivo.", "Un nuevo ámbito define un rango de direcciones, no una concesión fija garantizada para un dispositivo.", "Un CNAME es un alias de DNS y no controla qué dirección IP recibe la impresora."]],
  "sv25": ["Un host de hipervisor tiene una NIC física conectada a un puerto trunk. Las VM que corren en él deben estar en VLAN diferentes. ¿Qué se debe configurar?", ["IDs de VLAN en los port groups del switch virtual o en los adaptadores de las VM", "Un switch físico y un cable de uplink separados para cada VM", "NIC teaming en cada invitado", "Un relay DHCP en el host"], "Etiquetar el tráfico con IDs de VLAN en el switch virtual permite que un solo uplink trunk transporte varias VLAN. No se necesitan switches separados por VM.", [null, "Un switch físico por VM es innecesario porque un uplink trunk ya transporta todas las VLAN.", "NIC teaming en el invitado agrega enlaces para redundancia, no para separar VLAN.", "Un relay DHCP reenvía solicitudes DHCP entre subredes; no coloca las VM en VLAN."]],
  "sv26": ["Dos servidores web están detrás de un balanceador de carga. Uno suele tener muchas sesiones de larga duración mientras el otro está inactivo. ¿Qué algoritmo balancea esto mejor que round robin?", ["Hash de IP de origen", "Least connections (menos conexiones)", "Ponderación estática según la antigüedad del servidor", "DNS round robin"], "Least connections envía las nuevas solicitudes al servidor con menos sesiones activas, adaptándose a las conexiones de larga duración. Round robin ignora la carga actual.", ["El hash de IP de origen fija a cada cliente a un servidor según su dirección y no compensa las sesiones de distinta duración.", null, "Ponderar según la antigüedad del servidor es arbitrario e ignora qué tan ocupado está realmente cada servidor.", "DNS round robin solo rota los registros devueltos sin conocer la carga actual de los servidores."]],
  "sv27": ["Un clúster de dos nodos perdió el enlace de red entre los nodos, y ambos intentaron tomar posesión del disco compartido. ¿Qué evita esto?", ["DNS round robin", "Solo un heartbeat", "Un quórum con un testigo (witness)", "NIC teaming en la red de almacenamiento"], "Un testigo da a un lado el voto mayoritario, así que solo una partición sigue funcionando y se evita el split-brain. Un heartbeat detecta la falla, pero no puede desempatar.", ["DNS round robin distribuye las consultas de nombres y no hace nada para evitar el split-brain.", "Un heartbeat por sí solo puede detectar la falla de un nodo, pero no puede desempatar la propiedad del disco compartido.", null, "NIC teaming en la red de almacenamiento agrega redundancia de enlaces, pero no arbitra la propiedad del clúster."]],
  "sv28": ["Un nodo en espera permanece inactivo hasta que falla el servidor de base de datos principal y entonces toma el control. ¿Qué configuración es esta?", ["Activo-activo", "Clúster scale-out", "Con balanceo de carga", "Activo-pasivo"], "En un clúster activo-pasivo, el nodo pasivo espera para tomar el control ante una falla. Activo-activo ejecuta todos los nodos a la vez.", ["En un clúster activo-activo todos los nodos atienden tráfico al mismo tiempo, ninguno queda inactivo.", "Un clúster scale-out agrega nodos para crecer en capacidad, no un nodo pasivo en espera.", "El balanceo de carga reparte el trabajo entre nodos activos en lugar de mantener uno en espera.", null]],
  "sv29": ["Un servidor se conecta a una SAN mediante dos HBA y dos fabrics. ¿Qué software proporciona failover y reparto de carga entre ambas rutas?", ["RAID", "NIC teaming", "MPIO", "iSCSI CHAP"], "Multipath I/O gestiona varias rutas hacia el mismo LUN, haciendo failover y balanceando entre ellas. CHAP solo autentica sesiones iSCSI.", ["RAID proporciona redundancia de discos dentro de un arreglo, no failover entre rutas del fabric de la SAN.", "NIC teaming agrupa adaptadores Ethernet y no gestiona las rutas de los HBA de almacenamiento.", null, "iSCSI CHAP solo autentica sesiones iSCSI y no ofrece failover de rutas ni reparto de carga."]],
  "sv30": ["Una empresa quiere ejecutar VM de producción directamente sobre el hardware del servidor, sin un sistema operativo host. ¿Qué tipo de hipervisor es adecuado?", ["Emulador", "Tipo 2", "Runtime de contenedores", "Tipo 1"], "Los hipervisores Tipo 1 (bare-metal) como ESXi, Hyper-V y KVM se ejecutan directamente sobre el hardware. Tipo 2 se ejecuta sobre un sistema operativo de escritorio.", ["Un emulador simula hardware y es lento; no es un hipervisor bare-metal de producción.", "Un hipervisor Tipo 2 corre sobre un sistema operativo de escritorio host, no directamente sobre el hardware.", "Un runtime de contenedores comparte el kernel del host y no es un hipervisor a nivel de hardware.", null]],
  "sv31": ["Un host tiene 64 GB de RAM, pero a sus VM se les asignaron 96 GB en total. ¿Cómo se llama esta práctica?", ["Falla de memory ballooning", "Sobreasignación de memoria (overcommitment)", "Thin provisioning", "NUMA pinning"], "Asignar más recursos virtuales de los que existen físicamente es sobreasignación (overcommitment); funciona mientras las VM no usen toda su asignación al mismo tiempo. Thin provisioning se refiere al almacenamiento.", ["Ballooning es una técnica para recuperar memoria de los invitados, no el término para asignar más de lo que existe.", null, "Thin provisioning se refiere a asignar almacenamiento bajo demanda, no a la asignación de RAM.", "NUMA pinning vincula una VM a nodos específicos de CPU/memoria y no tiene relación con la sobreasignación."]],
  "sv32": ["Un administrador quiere un punto de reversión rápido antes de parchear una VM. ¿Qué debe tomar?", ["Un snapshot", "Un clon hacia un host nuevo", "Un respaldo completo a cinta", "Una plantilla"], "Un snapshot captura el estado de la VM para revertir rápidamente y debe eliminarse después del cambio. Las plantillas sirven para desplegar VM nuevas.", [null, "Clonar hace una copia completa a otro host, lo cual es más lento que un snapshot para una reversión rápida.", "Un respaldo completo a cinta es lento y está pensado para recuperación ante desastres, no para revertir rápido antes de un parche.", "Una plantilla es una imagen maestra para desplegar VM nuevas, no un punto de reversión para esta VM."]],
  "sv33": ["El disco virtual de una VM está configurado para usar espacio físico solo a medida que se escriben datos. ¿Qué es esto?", ["Thick provisioning", "Thin provisioning", "Deduplicación", "Disco pass-through"], "Los discos con thin provisioning crecen bajo demanda, ahorrando espacio pero con el riesgo de que el datastore se llene. Thick provisioning asigna todo al momento de la creación.", ["Thick provisioning asigna todo el espacio del disco desde el inicio, lo opuesto a crecer bajo demanda.", null, "La deduplicación elimina bloques de datos duplicados y es otra función de eficiencia de almacenamiento.", "Un disco pass-through asigna un disco físico directamente a la VM y no tiene que ver con el crecimiento bajo demanda."]],
  "sv34": ["Una empresa renta VM a un proveedor de nube y administra por su cuenta el sistema operativo, los parches y las aplicaciones. ¿Qué modelo de servicio es este?", ["SaaS", "PaaS", "FaaS", "IaaS"], "En IaaS el proveedor gestiona el hardware y la virtualización, mientras el cliente administra desde el sistema operativo hacia arriba. En PaaS el proveedor también administra el sistema operativo.", ["En SaaS el proveedor administra toda la aplicación, así que el cliente no parchearía el sistema operativo.", "En PaaS el proveedor administra el sistema operativo y el runtime, dejando al cliente solo las aplicaciones y los datos.", "FaaS son funciones serverless donde el cliente nunca administra un sistema operativo.", null]],
  "sv35": ["En un script de PowerShell, ¿qué operador de comparación verifica si $disk.FreeGB es menor que 10?", ["$disk.FreeGB -less 10", "$disk.FreeGB < 10", "$disk.FreeGB -lt 10", "$disk.FreeGB -le 1"], "PowerShell usa -lt para «menor que»; en PowerShell el símbolo < es un operador de redirección, no de comparación.", ["-less no es un operador de comparación válido en PowerShell.", "En PowerShell el símbolo < es un operador de redirección, no una comparación de «menor que».", null, "-le es «menor o igual que», y esta opción compara con 1 en lugar de con 10."]],
  "sv36": ["Un administrador necesita que un script de Bash se ejecute todas las noches a las 2:00 AM en un servidor Linux. ¿Qué debe usar?", ["Un cron job", "Una unidad mount de systemd", "Una entrada en .bashrc", "El comando at una sola vez"], "cron ejecuta tareas programadas de forma repetida (por ejemplo `0 2 * * *`). El comando at ejecuta una tarea una sola vez.", [null, "Una unidad mount de systemd monta sistemas de archivos y no es un programador de tareas.", "Una entrada en .bashrc se ejecuta al iniciar un shell interactivo, no según un horario nocturno.", "El comando at programa una tarea para ejecutarse una sola vez, no todas las noches."]],
  "sv37": ["Un script debe crear 200 cuentas de usuario listadas en un archivo CSV. ¿Qué construcción de scripting es la MÁS útil?", ["Un comparador", "Un bucle (loop)", "Una sola variable", "Un código de salida"], "Un bucle (como foreach) repite la creación de la cuenta para cada fila. Los comparadores solo evalúan valores.", ["Un comparador solo evalúa valores y no puede repetir la creación de cuentas para cada fila.", null, "Una sola variable guarda un solo valor y no puede recorrer 200 filas de un CSV.", "Un código de salida informa si el script tuvo éxito; no es una forma de repetir una acción."]],
  "sv38": ["¿Cuál es el principal riesgo de guardar la contraseña de un administrador en texto plano dentro de un script?", ["El script se ejecutará más lento", "El script no se podrá programar", "Cualquiera que lea el script obtiene la credencial", "Impide que las variables del script se pasen a funciones"], "Las credenciales en texto plano pueden ser leídas por cualquiera con acceso al archivo o a sus respaldos. En su lugar, use una bóveda de secretos, cuentas de servicio administradas o credenciales cifradas.", ["Guardar una contraseña en texto plano no afecta la velocidad de ejecución del script.", "Una credencial en texto plano no impide que el script se programe.", null, "Pasar una variable a una función sigue funcionando; el almacenamiento en texto plano no lo impide."]],
  "sv39": ["Un producto de base de datos se licencia por núcleo. Una empresa reemplaza un servidor de 16 núcleos por uno de 64 núcleos. ¿Qué pasa con el costo de licenciamiento?", ["Aumenta porque se deben licenciar más núcleos", "Se mantiene igual porque es un solo servidor", "Disminuye porque las CPU más nuevas completan el mismo trabajo en menos tiempo", "Solo cambia si aumentan los usuarios"], "El licenciamiento por núcleo escala con la cantidad de núcleos, así que cuatro veces más núcleos significa más licencias. Los modelos por servidor o por usuario no cambiarían.", [null, "El licenciamiento por núcleo no es por servidor, así que cuadruplicar los núcleos aumenta la cantidad de licencias.", "Terminar el trabajo más rápido no reduce la cantidad de núcleos que deben licenciarse.", "El costo por núcleo depende de los núcleos, no de la cantidad de usuarios."]],
  "sv40": ["Cada uno de 300 empleados accede a un servidor de archivos Windows desde varios dispositivos. ¿Qué modelo de Client Access License suele ser más económico?", ["CAL por dispositivo", "Licencia de sitio", "Licencias por socket", "CAL por usuario"], "Las CAL por usuario cubren a una persona en cualquier cantidad de dispositivos, así que son más baratas cuando los usuarios tienen varios dispositivos. Por dispositivo conviene para equipos compartidos.", ["Las CAL por dispositivo cuestan más cuando cada usuario se conecta desde varios dispositivos.", "Una licencia de sitio es amplia y normalmente mucho más cara de lo necesario para 300 usuarios.", "El licenciamiento por socket se basa en el hardware del servidor y no tiene relación con la cantidad de usuarios.", null]],
  "sv41": ["Un auditor pregunta cuándo vence la garantía de hardware de cada servidor. ¿Qué documento debe contener esto?", ["El inventario de activos", "El diagrama de red", "El registro de cambios", "El runbook del servicio"], "Los registros de activos llevan el control de números de serie, fechas de compra, garantía y estado del ciclo de vida. Los diagramas de red muestran las conexiones.", [null, "Un diagrama de red muestra cómo se conectan los dispositivos, no las fechas de vencimiento de las garantías.", "Un registro de cambios documenta las modificaciones hechas a los sistemas, no información de garantías.", "Un runbook documenta procedimientos operativos, no los detalles de garantía de los activos."]],
  "sv42": ["Un equipo documenta el uso normal de CPU, memoria y disco de un servidor nuevo durante su primer mes. ¿Cómo se llama este registro?", ["Un SLA", "Una línea base (baseline)", "Un catálogo de servicios", "Un análisis de causa raíz"], "Una línea base de rendimiento registra el comportamiento normal para que las anomalías posteriores resalten. Un SLA define compromisos de servicio.", ["Un SLA define compromisos y metas de servicio, no el uso normal de recursos medido.", null, "Un catálogo de servicios enumera los servicios ofrecidos a los usuarios, no mediciones de rendimiento.", "Un análisis de causa raíz explica un incidente después de ocurrido, no el comportamiento normal de referencia."]],
  "sv43": ["Antes de cambiar la configuración RAID de un servidor de producción, ¿qué debe aprobarse normalmente?", ["Un ticket de baja para la configuración anterior del arreglo", "Un nuevo SLA", "Una renovación de licencia", "Una solicitud de cambio mediante la gestión de cambios"], "La gestión de cambios revisa el riesgo, programa una ventana y documenta un plan de reversión antes de hacer cambios en producción. Un SLA no tiene relación con un cambio puntual.", ["Un ticket de baja sirve para retirar activos, no para modificar la configuración de un arreglo en funcionamiento.", "Un nuevo SLA establece compromisos de servicio y no es la aprobación que requiere un cambio de configuración.", "Una renovación de licencia cubre derechos de software y no tiene relación con un cambio de RAID.", null]],
  "sv44": ["Una tarea de respaldo hace un completo el domingo e incrementales de lunes a viernes. El servidor falla el jueves por la tarde. ¿Qué respaldos se necesitan para restaurar?", ["El completo del domingo y el incremental del miércoles, que incluye todos los cambios anteriores", "Solo el incremental del jueves", "El completo del domingo y cada incremental de lunes a jueves", "Solo el completo del domingo"], "Cada incremental contiene solo los cambios desde el respaldo anterior, así que se necesitan todos después del completo. Con diferenciales, solo se necesitaría el más reciente.", ["El domingo más solo el incremental del miércoles omite los cambios del jueves y los demás incrementales.", "El incremental del jueves por sí solo no tiene el completo base ni todos los cambios intermedios.", null, "Solo el completo perdería todos los cambios hechos durante la semana."]],
  "sv45": ["Las restauraciones deben ser lo más rápidas posible usando solo dos conjuntos de respaldo, y el tiempo de respaldo nocturno puede crecer durante la semana. ¿Qué esquema es adecuado?", ["Completo semanal con diferenciales diarios", "Completo semanal con incrementales diarios", "Solo un completo mensual", "Snapshots diarios guardados en el mismo volumen"], "Un diferencial contiene todos los cambios desde el último completo, así que una restauración solo necesita el completo y el diferencial más reciente. Los incrementales requieren todos los conjuntos de la cadena.", [null, "Los incrementales requieren restaurar el completo más cada conjunto de la cadena, es decir, más de dos conjuntos.", "Un completo mensual por sí solo deja una ventana enorme de pérdida de datos y ninguna restauración reciente rápida.", "Los snapshots diarios en el mismo volumen no son independientes y se pierden si ese volumen falla."]],
  "sv46": ["¿Qué práctica sigue MEJOR la regla de respaldo 3-2-1?", ["Tres respaldos al día, dos de ellos completos y uno probado", "Tres copias, en dos tipos de medios, con una copia fuera del sitio", "Tres servidores, dos sitios, una nube", "Tres snapshots en dos volúmenes de un mismo arreglo"], "3-2-1 significa tres copias de los datos en dos tipos de medios, con una copia guardada fuera del sitio. Los snapshots en un mismo arreglo fallan juntos.", ["Esto describe la frecuencia y las pruebas de respaldo, no la estructura de copias/medios/fuera del sitio de 3-2-1.", null, "Contar servidores y sitios confunde la infraestructura con las copias de datos y los tipos de medios requeridos.", "Los snapshots en un mismo arreglo fallan todos juntos y no cumplen ni la regla de dos medios ni la de copia fuera del sitio."]],
  "sv47": ["Los respaldos de una empresa se ejecutan todas las noches, pero nadie ha restaurado nunca a partir de ellos. ¿Cuál es el MAYOR riesgo?", ["Los respaldos tardan demasiado", "Los medios de respaldo se llenarán", "Los respaldos podrían no servir cuando se necesiten", "Los costos de licencia del software de respaldo subirán cada año"], "Los respaldos no probados pueden estar corruptos, incompletos o les pueden faltar datos, lo cual solo se descubre durante un desastre. Las restauraciones de prueba periódicas demuestran que la recuperación es posible.", ["Los tiempos de respaldo largos son un tema de rendimiento, no el peligro central de nunca probar restauraciones.", "Que los medios se llenen es un tema de capacidad y no dice si los datos realmente se pueden recuperar.", null, "El aumento de costos de licencia es un asunto de presupuesto, sin relación con si los respaldos pueden restaurarse."]],
  "sv48": ["Un negocio no puede perder más de 15 minutos de datos de pedidos después de una interrupción. ¿Qué métrica define esto?", ["RTO", "MTTR", "MTBF", "RPO"], "El RPO es la pérdida de datos máxima tolerable, medida en tiempo. El RTO es qué tan rápido debe restaurarse el servicio.", ["El RTO mide qué tan rápido debe restaurarse el servicio, no cuántos datos se pueden perder.", "El MTTR es el tiempo medio de reparación de una falla, una métrica de confiabilidad, no una meta de pérdida de datos.", "El MTBF es el tiempo medio entre fallas y no describe la pérdida de datos tolerable.", null]],
  "sv49": ["El sistema de nómina debe volver a funcionar dentro de las cuatro horas posteriores a un desastre. ¿Qué métrica define esto?", ["RPO", "MTBF", "RTO", "Crédito de SLA"], "El RTO es el tiempo máximo permitido para restaurar un servicio. El RPO mide la pérdida de datos aceptable.", ["El RPO es la cantidad aceptable de datos perdidos medida en tiempo, no qué tan rápido debe volver el servicio.", "El MTBF describe el tiempo esperado entre fallas, no un plazo de recuperación.", null, "Un crédito de SLA es una compensación por no cumplir un nivel de servicio, no una métrica de tiempo de recuperación."]],
  "sv50": ["Una empresa necesita un sitio de DR que pueda tomar el control en minutos con datos actualizados. El costo es una preocupación secundaria. ¿Qué tipo de sitio es adecuado?", ["Sitio frío (cold site)", "Sitio tibio (warm site)", "Acuerdo recíproco", "Sitio caliente (hot site)"], "Un hot site tiene equipos funcionando y datos actualizados para un failover casi inmediato. Un warm site necesita restaurar los datos primero.", ["Un cold site solo tiene espacio y energía, y tarda de días a semanas en ponerse en línea.", "Un warm site tiene hardware, pero necesita restaurar los datos primero, así que no puede hacer failover en minutos.", "Un acuerdo recíproco depende del sitio de otra organización, cuya disponibilidad es incierta.", null]],
  "sv51": ["Los datos se replican a un sitio de DR a 800 km de distancia. Las escrituras no deben esperar a que el sitio remoto confirme. ¿Qué tipo de replicación es adecuado?", ["Síncrona", "Asíncrona", "Solo snapshots", "RAID 1 en espejo"], "La replicación asíncrona confirma las escrituras localmente y las envía después, evitando la latencia de larga distancia a costa de una posible pérdida de datos. La síncrona espera a ambos sitios.", ["La replicación síncrona espera que el sitio remoto confirme cada escritura, lo que agrega mucha latencia a 800 km.", null, "La replicación solo con snapshots captura puntos periódicos en el tiempo en lugar de enviar escrituras de forma continua.", "RAID 1 en espejo duplica discos localmente y no replica hacia un sitio de DR lejano."]],
  "sv52": ["Los gerentes se reúnen para repasar cada paso del plan de DR ante una inundación simulada sin tocar ningún sistema. ¿Qué tipo de prueba es esta?", ["Ejercicio de mesa (tabletop)", "Prueba de failover en vivo", "Prueba en paralelo", "Prueba de interrupción total"], "Un ejercicio de mesa recorre el plan solo mediante discusión. Un failover en vivo realmente traslada la producción al sitio de DR.", [null, "Una prueba de failover en vivo realmente traslada la producción al sitio de DR, lo que este ejercicio evita.", "Una prueba en paralelo ejecuta los sistemas de DR junto a la producción usando infraestructura real, no solo discusión.", "Una prueba de interrupción total apaga la producción para probar el DR; es el tipo más disruptivo."]],
  "sv53": ["Los SSD viejos de servidores retirados deben quedar irrecuperables antes de desecharlos. ¿Qué método es confiable?", ["Desmagnetización (degaussing)", "Formateo rápido", "Eliminar las particiones", "Trituración física"], "La trituración destruye los chips flash. La desmagnetización no afecta a los SSD, y formatear o eliminar particiones deja los datos recuperables.", ["La desmagnetización borra medios magnéticos y no tiene efecto sobre la memoria flash de un SSD.", "Un formateo rápido solo limpia la tabla de archivos y deja los datos subyacentes recuperables.", "Eliminar particiones quita la tabla de particiones, pero deja los datos reales intactos.", null]],
  "sv54": ["Después de que un proveedor destruye un lote de discos duros viejos, ¿qué debe conservar la empresa en sus registros?", ["Un certificado de destrucción", "Las tarjetas de garantía de los discos", "Una nueva línea base", "La orden de compra original y los comprobantes de envío"], "Un certificado de destrucción documenta qué activos se destruyeron, cuándo y cómo, lo que respalda auditorías y cumplimiento normativo.", [null, "Las tarjetas de garantía tienen que ver con derechos de soporte, no con la prueba de que los discos se destruyeron.", "Una nueva línea base registra el comportamiento de rendimiento y no tiene relación con el desecho de medios.", "Las órdenes de compra y los comprobantes de envío documentan la adquisición, no la destrucción segura."]],
  "sv55": ["Un servidor web nuevo tiene FTP, Telnet y una cola de impresión en ejecución, pero solo necesita HTTPS. ¿Cuál es el PRIMER paso de hardening?", ["Instalar una segunda NIC", "Deshabilitar o eliminar los servicios innecesarios", "Aumentar el nivel de RAID", "Habilitar jumbo frames en la interfaz de red del servidor"], "Eliminar los servicios que no se necesitan cierra puertos y reduce la superficie de ataque. Además, Telnet envía las credenciales en texto claro.", ["Agregar una segunda NIC da redundancia de red, no una reducción de la superficie de ataque.", null, "Subir el nivel de RAID mejora la resiliencia del almacenamiento, pero no endurece el sistema operativo.", "Habilitar jumbo frames ajusta el rendimiento de la red y no es un paso de hardening de seguridad."]],
  "sv56": ["Los administradores se conectan a servidores Linux con contraseñas por SSH, y los logs muestran intentos constantes de fuerza bruta. ¿Qué cambio mejora MÁS la seguridad?", ["Cambiar SSH por Telnet", "Permitir el login directo de root para aplicar correcciones más rápido", "Usar autenticación basada en llaves y deshabilitar el login con contraseña", "Apagar el firewall del host"], "SSH basado en llaves anula por completo el adivinado de contraseñas. Telnet no está cifrado y permitir el login de root aumenta el riesgo.", ["Telnet no está cifrado y es mucho menos seguro que SSH, así que cambiarse a él empeora la seguridad.", "Permitir el login directo de root aumenta el riesgo de que un compromiso obtenga control total.", null, "Apagar el firewall del host expone más servicios y debilita la seguridad."]],
  "sv57": ["Un grupo de mesa de ayuda necesita restablecer contraseñas, pero no debe administrar servidores. ¿Qué principio guía esto?", ["Separación de funciones", "Defensa en profundidad", "Mínimo privilegio", "Confianza implícita"], "El mínimo privilegio otorga solo los derechos necesarios para un trabajo. La separación de funciones divide las tareas críticas entre personas, lo cual está relacionado pero es distinto.", ["La separación de funciones divide las tareas críticas entre personas; está relacionada, pero no trata sobre derechos mínimos.", "La defensa en profundidad superpone varios controles y no se trata específicamente de limitar los derechos de las cuentas.", null, "La confianza implícita es lo opuesto a un diseño seguro y otorga acceso sin verificación."]],
  "sv58": ["Las cuentas se asignan a grupos como 'DB-Admins' y los permisos se otorgan a los grupos. ¿Qué modelo es este?", ["Control de acceso discrecional", "Control de acceso basado en roles", "Control de acceso obligatorio", "Control de acceso basado en reglas"], "RBAC otorga derechos a roles o grupos, y los usuarios los heredan por su membresía. MAC usa etiquetas y autorizaciones (clearances).", ["El control de acceso discrecional permite que los dueños de los objetos definan permisos individualmente, no mediante grupos de roles.", null, "El control de acceso obligatorio usa etiquetas de seguridad y autorizaciones que impone el sistema.", "El control de acceso basado en reglas aplica condiciones como horario o ACL, no la membresía en un rol."]],
  "sv59": ["¿Qué control físico evita que una persona entre siguiendo a otra por una puerta segura del data center?", ["Un vestíbulo de control de acceso (mantrap)", "Solo un lector de credenciales", "Una cámara CCTV", "Puertas de rack con llave"], "Un vestíbulo deja pasar a una persona a la vez entre dos puertas, lo que detiene el tailgating. Una cámara solo lo graba.", [null, "Un lector de credenciales por sí solo no impide que una segunda persona se cuele detrás de una autorizada.", "Una cámara CCTV graba el tailgating después de que ocurre, pero no lo impide físicamente.", "Las puertas de rack con llave protegen los racks de equipos, no la entrada del data center."]],
  "sv60": ["Se robaron una laptop que contenía una copia de la base de datos de un servidor. ¿Qué control probablemente habría protegido los datos?", ["NIC teaming", "Un candado de cable en el servidor", "Una concesión DHCP más larga", "Cifrado de disco completo"], "El cifrado de disco completo mantiene ilegibles los datos en reposo sin la llave. Los datos estaban en el dispositivo robado, no en el servidor.", ["NIC teaming proporciona redundancia de red y no protege los datos almacenados.", "Un candado de cable asegura el servidor, pero aquí lo que se robaron fue la laptop.", "Una concesión DHCP más larga solo afecta el direccionamiento y no protege datos.", null]],
  "sv61": ["Un administrador quiere impedir que cualquiera en la consola cambie el orden de arranque para iniciar un sistema operativo live desde USB. ¿Qué debe configurar?", ["Un tiempo de espera del protector de pantalla más largo", "Una contraseña de administrador de BIOS/UEFI", "Un registro DNS PTR", "Port security en el puerto del switch que usa el servidor"], "Una contraseña de firmware bloquea los cambios no autorizados en la configuración de arranque. Los protectores de pantalla no protegen el firmware.", ["El tiempo de espera del protector de pantalla es un bloqueo a nivel de sistema operativo y no impide cambios en el firmware ni en el orden de arranque.", null, "Un registro DNS PTR asocia una IP con un nombre y no tiene relación con la seguridad del firmware.", "Port security del switch controla direcciones MAC en la red, no la configuración de arranque del servidor."]],
  "sv62": ["¿Qué herramienta puede detectar y bloquear archivos sensibles, como registros de clientes, para que no se copien a unidades USB ni se envíen por correo?", ["MPIO", "IDS", "NTP", "DLP"], "La prevención de pérdida de datos (DLP) inspecciona los datos en uso y en tránsito y bloquea las transferencias que coinciden con la política. Un IDS detecta ataques de red.", ["MPIO gestiona rutas de almacenamiento redundantes y no tiene nada que ver con bloquear la exfiltración de datos.", "Un IDS detecta intrusiones de red, pero no aplica políticas sobre archivos copiados a USB o enviados por correo.", "NTP sincroniza relojes y no ofrece protección contra pérdida de datos.", null]],
  "sv63": ["Un ransomware cifró un servidor de archivos y también los respaldos guardados en un recurso compartido de red al que tenía acceso. ¿Qué cambio protege MEJOR los respaldos futuros?", ["Mantener una copia offline o inmutable de los respaldos", "Respaldar con más frecuencia al mismo recurso compartido", "Cambiar a respaldos diferenciales", "Usar un arreglo RAID 6 más grande con más discos de paridad"], "Los respaldos offline, aislados (air-gapped) o inmutables no pueden ser alterados por un ransomware en la red. Respaldar más seguido al mismo recurso compartido los deja expuestos.", [null, "Respaldar más seguido al mismo recurso accesible sigue dejando esas copias expuestas al cifrado.", "Elegir respaldos diferenciales cambia el tipo de respaldo, pero no la capacidad del ransomware de alcanzarlos.", "Un arreglo RAID 6 más grande protege contra fallas de disco, no contra un ransomware que cifra los archivos."]],
  "sv64": ["Una rotación de respaldos mantiene conjuntos diarios, semanales y mensuales, reutilizando cada semana los medios diarios. ¿Qué esquema es este?", ["Torre de Hanói", "3-2-1", "Abuelo-padre-hijo (GFS)", "Primero en entrar, primero en salir"], "GFS conserva hijos (diarios), padres (semanales) y abuelos (mensuales) para una retención más larga. 3-2-1 es una regla de ubicación de copias, no una rotación.", ["La Torre de Hanói es otra rotación basada en intervalos de reutilización recursivos, no en conjuntos diarios/semanales/mensuales.", "3-2-1 es una regla de ubicación de copias sobre medios y copias fuera del sitio, no una rotación de retención.", null, "FIFO simplemente sobrescribe el medio más antiguo y no tiene la retención escalonada diaria/semanal/mensual."]],
  "sv65": ["La política de la empresa dice que los registros financieros deben conservarse siete años y luego eliminarse. ¿Cómo se llama esta política?", ["Clasificación de datos", "Enmascaramiento de datos", "Soberanía de datos", "Retención de datos"], "Una política de retención establece cuánto tiempo se conservan los datos y cuándo se eliminan. La soberanía de datos trata sobre qué leyes de qué país aplican según dónde se almacenan los datos.", ["La clasificación de datos etiqueta qué tan sensibles son los datos, no cuánto tiempo deben conservarse.", "El enmascaramiento de datos oculta valores para protegerlos y no tiene relación con los periodos de retención.", "La soberanía de datos trata sobre qué leyes de qué país rigen el lugar donde se almacenan los datos.", null]],
  "sv66": ["Un técnico identificó el problema de un servidor. ¿Cuál es el siguiente paso en la metodología de troubleshooting de CompTIA?", ["Establecer una teoría de la causa probable", "Implementar la solución", "Documentar los hallazgos", "Verificar la funcionalidad completa del sistema"], "Después de identificar el problema, el técnico formula una teoría de la causa probable y luego la prueba. La implementación viene después.", [null, "Implementar la solución viene solo después de un plan de acción, mucho más adelante en el proceso.", "Documentar los hallazgos es el último paso, no lo que sigue a la identificación del problema.", "La verificación de la funcionalidad ocurre cerca del final, después de implementar la solución."]],
  "sv67": ["Antes de hacer cambios para reparar un servidor con fallas, ¿qué debe hacer el técnico como parte de la identificación del problema?", ["Reemplazar la tarjeta madre", "Hacer un respaldo si es posible", "Documentar las lecciones aprendidas", "Escalar de inmediato"], "La metodología indica respaldar cuando sea posible antes de hacer cambios, para que los datos estén seguros. La documentación va al final.", ["Reemplazar la tarjeta madre es una acción de reparación, no parte de la identificación del problema.", null, "Documentar las lecciones aprendidas es el último paso de la metodología, no uno de los primeros.", "Escalar de inmediato se salta la investigación que requiere la identificación."]],
  "sv68": ["Un técnico reparó un servicio caído y confirmó que los usuarios pueden trabajar. ¿Qué debe hacerse al final?", ["Volver a entrevistar a los usuarios", "Establecer una nueva teoría", "Documentar hallazgos, acciones y resultados", "Reiniciar el servidor"], "La documentación es el último paso, para que la solución quede registrada para futuros incidentes. La verificación de la funcionalidad va justo antes.", ["Entrevistar a los usuarios es parte de la identificación del problema, no el paso de cierre.", "Establecer una teoría ocurre al principio, mucho antes de verificar la solución.", null, "Reiniciar es una posible acción, no el paso final de documentación."]],
  "sv69": ["Un servidor emite pitidos al encenderse y no llega al sistema operativo. ¿Cuál es la causa MÁS probable que se debe revisar primero?", ["Una mala configuración de DNS", "Un certificado vencido", "Una falla de hardware en el POST, como la memoria", "Un volumen de datos lleno"], "Los códigos de pitidos son mensajes del POST sobre el hardware, comúnmente memoria, CPU o video. El DNS y los certificados importan solo después de que carga el sistema operativo.", ["Una mala configuración de DNS solo importa una vez que carga el sistema operativo, no en los pitidos al encender.", "Un certificado vencido es un problema del sistema operativo o de la aplicación, no una falla de hardware del POST.", null, "Un volumen de datos lleno es un problema del sistema operativo y no produciría códigos de pitidos al encender."]],
  "sv70": ["Un servidor se apaga solo todas las tardes, y el log del BMC muestra eventos de temperatura de entrada alta. ¿Cuál es la causa MÁS probable?", ["Problemas de enfriamiento en la sala o en el rack", "Una NIC con fallas", "Una fuga de memoria del sistema operativo", "Un registro DNS incorrecto"], "Una temperatura de entrada alta significa que el aire que entra está demasiado caliente, lo que apunta al HVAC, a un flujo de aire bloqueado o a recirculación de aire caliente. Una falla de NIC no provocaría un apagado térmico.", [null, "Una NIC con fallas afecta la red y no provocaría un apagado térmico.", "Una fuga de memoria causa lentitud gradual o caídas, no eventos de temperatura de entrada alta.", "Un registro DNS incorrecto afecta la resolución de nombres, no la temperatura del servidor."]],
  "sv71": ["El sistema operativo reporta errores de memoria corregidos en un DIMM varias veces al día. ¿Qué debe hacer el administrador?", ["Ignorarlos porque ECC los corrigió", "Programar el reemplazo de ese DIMM", "Aumentar el espacio de swap", "Deshabilitar ECC en el firmware"], "El aumento de errores corregibles suele llevar a errores no corregibles, así que el DIMM debe reemplazarse en una ventana de mantenimiento. Deshabilitar ECC elimina la protección.", ["Ignorar el aumento de errores corregibles es riesgoso porque suelen preceder a fallas no corregibles.", null, "Aumentar el swap es paginación en disco y no repara un DIMM que se está degradando.", "Deshabilitar ECC elimina justamente la protección que está detectando estos errores."]],
  "sv72": ["Una de las fuentes de poder de un par redundante muestra un LED ámbar, pero el servidor sigue funcionando. ¿Cuál es la acción correcta?", ["Apagar el servidor de inmediato", "Actualizar el sistema operativo", "Mover toda la carga a un hipervisor Tipo 2", "Reemplazar la PSU hot-swap fallada y revisar su alimentación eléctrica"], "Las PSU redundantes mantienen el servidor funcionando, pero la unidad fallada (o su alimentación) debe repararse para restablecer la redundancia. No es necesario apagarlo de inmediato.", ["Apagar de inmediato es innecesario porque la fuente redundante mantiene el servidor funcionando.", "Actualizar el sistema operativo no tiene relación con una fuente de poder fallada.", "Mover la carga a un hipervisor Tipo 2 no tiene sentido como respuesta a una falla de PSU.", null]],
  "sv73": ["Un arreglo RAID 5 aparece como degradado después de que falló un disco. ¿Cuál es el principal riesgo hasta que se reconstruya?", ["Consultas DNS más lentas", "La licencia del sistema operativo vencerá", "El arreglo se convertirá automáticamente en RAID 0", "Una segunda falla de disco hará perder el arreglo"], "RAID 5 tolera solo una falla; otra falla antes de que termine la reconstrucción destruye el arreglo. Reemplace el disco pronto y revise los respaldos.", ["Las consultas DNS más lentas no tienen relación con el estado de un arreglo RAID degradado.", "La licencia del sistema operativo no vence porque un arreglo esté degradado.", "Un arreglo RAID 5 degradado no se convierte automáticamente en RAID 0.", null]],
  "sv74": ["Después de un corte de energía, un servidor muestra 'boot device not found'. Los discos giran con normalidad. ¿Qué debe revisar PRIMERO el administrador?", ["El orden de arranque y la configuración de la controladora RAID en el firmware", "El servidor DNS", "La clave de licencia", "El modo de NIC teaming"], "Una configuración de firmware o de controladora que se restableció puede cambiar el orden de arranque u ocultar el arreglo. El DNS y el licenciamiento no afectan si el disco se detecta al arrancar.", [null, "El DNS no tiene ningún papel en si el firmware puede encontrar un dispositivo de arranque.", "Una clave de licencia afecta la activación del sistema operativo, no la capacidad del hardware de encontrar el disco al arrancar.", "NIC teaming es una configuración de red y no tiene nada que ver con encontrar el disco de arranque."]],
  "sv75": ["Los datos SMART de un disco muestran un conteo creciente de sectores reasignados. ¿Qué indica esto?", ["El disco está sano y optimizándose", "Es probable que el disco falle y debe reemplazarse", "El sistema de archivos necesita desfragmentarse", "La caché de la controladora RAID está llena"], "Los sectores reasignados significan que el disco está remapeando áreas dañadas; un conteo creciente predice una falla. Desfragmentar no ayuda.", ["Los sectores reasignados señalan degradación, no un disco sano que se optimiza.", null, "Desfragmentar reorganiza archivos y no puede reparar sectores físicamente dañados.", "Una caché de controladora llena no tiene relación con el conteo de sectores reasignados de SMART."]],
  "sv76": ["La aplicación de un servidor Linux falla con 'No space left on device', pero `df -h` muestra 40% libre. ¿Qué debe revisar el administrador a continuación?", ["La concesión DHCP", "El gateway predeterminado", "El uso de inodos con df -i", "La llave SSH"], "Un volumen puede quedarse sin inodos cuando contiene muchos archivos pequeños, aunque tenga bloques libres. `df -i` muestra el uso de inodos.", ["Una concesión DHCP tiene que ver con el direccionamiento IP y no con un error de espacio en disco.", "El gateway predeterminado es una configuración de enrutamiento, sin relación con quedarse sin espacio.", null, "Una llave SSH sirve para autenticación y no afecta la capacidad de almacenamiento."]],
  "sv77": ["Después de un apagado inesperado, un volumen de datos Linux no se monta y reporta errores del sistema de archivos. ¿Qué herramienta lo repara?", ["chmod sobre el punto de montaje", "fsck sobre el volumen desmontado", "ping al arreglo de almacenamiento", "top"], "fsck verifica y repara sistemas de archivos Linux y debe ejecutarse con el volumen desmontado. chmod solo cambia permisos.", ["chmod cambia los permisos del punto de montaje y no repara un sistema de archivos corrupto.", null, "ping solo prueba la conectividad de red hacia el arreglo, no la integridad del sistema de archivos.", "top muestra los procesos en ejecución y no puede reparar un sistema de archivos."]],
  "sv78": ["La latencia de escritura en disco de una controladora RAID se disparó después de que falló la batería de la controladora. ¿Qué es lo MÁS probable que haya ocurrido?", ["El arreglo cambió de nivel de RAID", "La NIC bajó a 100 Mbps", "Los discos se pusieron en solo lectura", "La controladora cambió la caché de write-back a write-through"], "Sin una batería o respaldo flash en buen estado, las controladoras deshabilitan la caché write-back para proteger los datos, así que las escrituras van directo al disco y se vuelven más lentas.", ["Una batería de caché fallada no cambia el nivel de RAID del arreglo.", "La velocidad de la NIC es un tema de red y no tiene relación con la latencia de escritura en disco.", "Una batería de caché agotada no pone los discos en solo lectura.", null]],
  "sv79": ["La memoria disponible de un servidor Windows baja de forma constante durante dos semanas hasta que se pone lento, y un reinicio lo arregla por un tiempo. ¿Cuál es la causa MÁS probable?", ["Una fuga de memoria en un proceso", "Una fuente de poder fallada", "Un desajuste de dúplex", "Una máscara de subred incorrecta"], "La pérdida gradual de memoria que se resuelve con un reinicio es típica de una fuga de memoria. Seguir la tendencia de memoria por proceso en Performance Monitor permite encontrar al culpable.", [null, "Una fuente de poder fallada causa una caída, no una disminución lenta y constante de la memoria disponible.", "Un desajuste de dúplex degrada el rendimiento de red, no la disponibilidad de memoria.", "Una máscara de subred incorrecta afecta la conectividad, no el uso de memoria del servidor."]],
  "sv80": ["Un servicio de Windows no arranca después de que se cambió la contraseña de su cuenta de servicio. ¿Cuál es la solución MÁS probable?", ["Reinstalar el sistema operativo", "Cambiar el servicio a manual", "Actualizar la contraseña guardada en la configuración Log On del servicio", "Agregar más RAM"], "Los servicios que se ejecutan con una cuenta de dominio guardan una copia de la contraseña, que debe actualizarse después de un cambio. Reinstalar es excesivo.", ["Reinstalar el sistema operativo es mucho más trabajo del necesario para corregir una contraseña de cuenta de servicio cambiada.", "Poner el servicio en manual cambia su tipo de inicio, pero no corrige la contraseña guardada incorrecta.", null, "Agregar RAM no tiene relación con un servicio que falla por un cambio de credenciales."]],
  "sv81": ["Después de un parche mensual, una aplicación crítica en un servidor deja de funcionar. Otros servidores sin el parche están bien. ¿Qué debe hacer PRIMERO el administrador?", ["Cambiar la dirección IP del servidor", "Deshabilitar el firewall del host", "Reemplazar el servidor", "Revertir el parche según el plan de cambios y probar"], "El parche es la causa probable, así que revertirlo restablece el servicio mientras se investiga el problema. Deshabilitar el firewall agrega riesgo y no atiende el cambio.", ["Cambiar la dirección IP del servidor no tiene relación con una falla causada por un parche.", "Deshabilitar el firewall del host agrega riesgo y no atiende el parche problemático.", "Reemplazar el servidor es drástico cuando el parche reciente es el sospechoso obvio.", null]],
  "sv82": ["Un servicio de Linux no arranca. ¿Qué comando muestra sus mensajes de log recientes?", ["journalctl -u <service>", "ip route", "df -h", "lsblk"], "journalctl con -u filtra el journal de systemd para esa unidad y muestra por qué falló. lsblk lista los dispositivos de bloque.", [null, "ip route muestra la tabla de enrutamiento, no los mensajes de log de un servicio.", "df -h muestra el uso de espacio en disco, no por qué falló un servicio.", "lsblk lista dispositivos de bloque y no revela nada sobre los logs de un servicio."]],
  "sv83": ["Un servidor puede llegar a otros hosts de su subred, pero a nada en redes remotas. ¿Cuál es la causa MÁS probable?", ["Un servidor DNS incorrecto", "Un gateway predeterminado incorrecto o ausente", "Un arreglo RAID fallado", "Un certificado vencido"], "El tráfico hacia otras redes pasa por el gateway predeterminado; si es incorrecto, solo funcionan los hosts locales. El DNS afecta la resolución de nombres, no la conectividad por IP.", ["Un servidor DNS incorrecto rompe la resolución de nombres, pero no la conectividad por IP hacia redes remotas.", null, "Un arreglo RAID fallado es un problema de almacenamiento y no afecta la conectividad de red.", "Un certificado vencido es un problema de seguridad de la aplicación, no una falla de enrutamiento."]],
  "sv84": ["Los usuarios pueden llegar a un servidor por su dirección IP, pero no por su nombre. ¿Qué herramienta debe usar PRIMERO el administrador?", ["arp -a", "tracert", "nslookup o dig", "netstat -r"], "Una falla de nombres con acceso por IP funcionando apunta al DNS, que nslookup o dig prueban directamente. tracert prueba la ruta, no la resolución de nombres.", ["arp -a muestra la caché local de IP a MAC y no prueba la resolución de nombres DNS.", "tracert traza la ruta de red por saltos, no si un nombre se resuelve.", null, "netstat -r imprime la tabla de enrutamiento, que no tiene relación con la resolución de nombres."]],
  "sv85": ["Una aplicación web en un servidor no es accesible desde los clientes, aunque ping funciona. El administrador quiere probar desde un cliente si el puerto TCP 443 está abierto. ¿Qué comando es adecuado?", ["arp -d", "ipconfig /flushdns", "Test-NetConnection server -Port 443", "chkdsk /f"], "Test-NetConnection (o telnet/nc) intenta una conexión TCP a un puerto y muestra si el servicio o el firewall la bloquean. flushdns solo limpia la caché de nombres.", ["arp -d limpia la caché ARP y no prueba si un puerto TCP está abierto.", "ipconfig /flushdns limpia la caché DNS y no sondea ningún puerto.", null, "chkdsk /f revisa un disco en busca de errores y no tiene nada que ver con probar un puerto."]],
  "sv86": ["El enlace de un servidor está lento y el puerto del switch muestra muchas colisiones tardías, mientras que el lado del servidor no muestra ninguna. ¿Cuál es la causa MÁS probable?", ["Un desajuste de dúplex", "Una mala configuración de DNS", "Una VLAN incorrecta", "Un gateway incorrecto"], "Las colisiones tardías en un solo lado indican que un extremo está en half duplex y el otro en full. Configure ambos extremos igual o en autonegociación.", [null, "Una mala configuración de DNS rompería la resolución de nombres, no causaría colisiones tardías en un enlace.", "Una VLAN incorrecta aislaría el tráfico en lugar de producir colisiones tardías.", "Un gateway incorrecto es un problema de enrutamiento y no genera colisiones."]],
  "sv87": ["Un servidor con IP estática muestra advertencias de 'dirección IP duplicada' después de que se agregó una impresora nueva. ¿Cuál es la causa MÁS probable?", ["El reloj del servidor está mal", "La NIC del servidor está fallando", "La zona DNS está corrupta", "La impresora obtuvo la dirección del servidor desde el pool de DHCP"], "Si una dirección estática está dentro del ámbito DHCP, a un dispositivo nuevo se le puede conceder la misma dirección. Excluya o reserve las direcciones estáticas.", ["Un reloj incorrecto es un problema de sincronización de hora y no crea una dirección IP duplicada.", "Una NIC con fallas causaría problemas de enlace, no una advertencia de dirección duplicada.", "Una zona DNS corrupta afecta la resolución de nombres, no los conflictos de direcciones IP.", null]],
  "sv88": ["Después de que venció el certificado TLS de un servidor, los clientes ven advertencias de seguridad. ¿Qué debe hacer el administrador?", ["Deshabilitar TLS en el servidor", "Renovar e instalar un certificado nuevo y configurar un recordatorio de renovación", "Cambiar la dirección IP del servidor", "Reiniciar el servicio DNS"], "Un certificado vencido debe reemplazarse; dar seguimiento a la renovación o automatizarla evita que se repita. Deshabilitar TLS elimina el cifrado.", ["Deshabilitar TLS elimina el cifrado por completo y deja a los clientes sin protección.", null, "Cambiar la dirección IP del servidor no tiene relación con un certificado vencido.", "Reiniciar el servicio DNS no renueva ni reemplaza un certificado vencido."]],
  "sv89": ["Un usuario puede abrir una carpeta compartida, pero no puede guardar archivos, aunque el permiso del recurso compartido es Full Control. ¿Cuál es la causa MÁS probable?", ["El registro DNS es incorrecto", "Los permisos NTFS solo permiten lectura (Read)", "El servidor no tiene gateway predeterminado", "El disco está en RAID 1"], "Los permisos del recurso compartido y NTFS se combinan y se aplica el más restrictivo, así que Read en NTFS bloquea las escrituras. Un problema de DNS impediría incluso abrir el recurso compartido.", ["Un registro DNS incorrecto impediría llegar al recurso compartido, no solo bloquear el guardado de archivos.", null, "La falta de gateway bloquearía el acceso por completo, pero el usuario ya puede abrir el recurso compartido.", "RAID 1 es redundancia de discos, no un control de permisos que bloquee las escrituras."]],
  "sv90": ["Después de instalar una nueva protección de endpoints, una aplicación de línea de negocio en un servidor deja de iniciar. ¿Cuál es la causa MÁS probable?", ["El NIC team se separó", "Falló la batería del RAID", "El software de seguridad puso en cuarentena o bloqueó los archivos de la aplicación", "El ámbito DHCP se agotó"], "Un antivirus o EDR nuevo puede marcar ejecutables legítimos; revise su cuarentena y agregue una exclusión verificada. Los otros problemas no aparecerían justo después de esa instalación.", ["Un NIC team separado es un problema de red y no impediría que una aplicación inicie.", "Una batería de RAID fallada ralentiza las escrituras, pero no bloquearía una aplicación justo después de instalar un antivirus.", null, "Un ámbito DHCP agotado afecta el direccionamiento, no una aplicación bloqueada después de instalar un EDR."]],
  "x1": ["Un servidor de 1U en rieles deslizables a veces debe sacarse hacia adelante para darle servicio mientras sigue funcionando. ¿Qué evita que sus cables de energía y red se tensen o se desconecten al deslizarlo?", ["Cintas de velcro que sujetan los cables firmemente al poste trasero del rack", "Cables patch y de energía más cortos para que no haya holgura que se enganche", "Un brazo de gestión de cables fijado a la parte trasera de los rieles", "Un PDU vertical montado directamente detrás del servidor"], "Un brazo de gestión de cables se pliega y se extiende junto con el servidor, así que los cables lo siguen al deslizarlo. Atar los cables firmemente al poste es la opción tentadora, pero elimina la holgura que necesita el servidor y afloja los conectores.", ["Atar los cables firmemente al poste elimina la holgura que necesita el servidor, así que al deslizarlo se sueltan los conectores.", "Los cables más cortos empeoran el problema; sin holgura, los cables se desconectan en cuanto el servidor se mueve.", null, "Un PDU es una fuente de energía, no una forma de guiar cables en movimiento, y no hace nada por el cableado de red."]],
  "x2": ["La fuente de poder de un chasis blade de alta potencia tiene una entrada C20. ¿Qué conector debe tener el extremo del cable de energía que se conecta a ella?", ["C19", "C13", "C14", "NEMA 5-15P"], "Los conectores IEC C19 encajan con las entradas C20 y se usan para equipos de mayor corriente. C13 es la respuesta tentadora común, pero C13 encaja con la entrada C14, más pequeña, que tienen las PSU típicas de servidores.", [null, "Los conectores C13 encajan con entradas C14, que son el tipo más pequeño y de menor corriente de las PSU típicas de servidores.", "C14 es en sí un tipo de entrada; el extremo del cable debe ser el conector correspondiente, y C14 no encaja en una C20.", "NEMA 5-15P es un enchufe de pared norteamericano, no un conector IEC que encaje en la entrada de un equipo."]],
  "x3": ["Dos salas de datos a unos 8 km de distancia necesitan un enlace de 10 Gbps entre sus switches core. ¿Qué combinación de transceptor y cableado es adecuada?", ["Ópticas SFP+ de corto alcance sobre fibra multimodo OM3", "Ópticas SFP+ de largo alcance sobre fibra monomodo", "Un cable twinax DAC pasivo tendido entre las salas", "Puertos 10GBASE-T sobre cobre Cat6a blindado"], "Las ópticas de 10 Gb de largo alcance sobre fibra monomodo están diseñadas para distancias de varios kilómetros. Las ópticas de corto alcance sobre multimodo OM3 son tentadoras porque son más baratas, pero solo alcanzan unos cientos de metros.", ["Las ópticas multimodo de corto alcance solo llegan a unos cientos de metros, muy lejos de 8 km.", null, "Los cables DAC pasivos están pensados solo para unos pocos metros, por ejemplo dentro de un rack o entre racks adyacentes.", "10GBASE-T sobre Cat6a está limitado a unos 100 metros de cobre."]],
  "x4": ["Un servidor de archivo guardará archivos de video a los que se accede muy poco. Lo que más importa es la capacidad por dólar y las necesidades de rendimiento son bajas. ¿Qué discos son los MEJORES?", ["Discos SAS de 15K RPM en bahías de factor de forma pequeño", "SSD NVMe instalados en bahías hot-swap U.2", "Discos SAS de 10K RPM en carriers de 2.5 pulgadas", "Discos nearline de alta capacidad de 7.2K RPM"], "Los discos nearline de 7.2K RPM dan la mayor capacidad por el dinero y funcionan bien para datos de archivo fríos y secuenciales. Los discos SAS de 10K RPM son tentadores como punto intermedio, pero cuestan más por terabyte y ofrecen menos capacidad sin un beneficio real aquí.", ["Los discos SAS de 15K son rápidos pero caros y de baja capacidad; se desperdician en datos de archivo que casi no se leen.", "Los SSD NVMe cuestan mucho más por terabyte y su velocidad no se necesita para almacenamiento de archivo frío.", "Los discos SAS de 10K siguen costando más por terabyte que los nearline, con poco beneficio para archivo.", null]],
  "x5": ["Una base de datos con muchas escrituras se colocó en RAID 6. Comparado con RAID 10 en los mismos discos, ¿por qué su rendimiento de escritura es notablemente peor?", ["Cada escritura pequeña debe leer y actualizar dos bloques de paridad, lo que cuesta E/S de disco adicional", "RAID 6 distribuye los datos en menos discos que RAID 10", "RAID 6 replica cada bloque en tres discos antes de confirmar", "RAID 6 no puede usarse con la caché write-back de una controladora"], "RAID 6 mantiene paridad doble, así que cada escritura pequeña provoca lecturas y escrituras adicionales para actualizar ambos bloques de paridad (una alta penalización de escritura). La respuesta del espejo es incorrecta porque RAID 6 usa paridad, no espejo; RAID 10 es el nivel que hace espejo.", [null, "RAID 6 y RAID 10 pueden abarcar la misma cantidad de discos; la diferencia es la paridad doble, no el ancho del stripe.", "RAID 6 usa paridad, no espejo; RAID 10 es el nivel que replica los bloques en espejo.", "RAID 6 funciona bien con caché write-back, que de hecho ayuda a ocultar su penalización de escritura."]],
  "x6": ["Un servidor de laboratorio tiene cuatro discos de distintos tamaños. El administrador quiere presentarlos como un solo volumen grande usando toda su capacidad y acepta que no haya redundancia. ¿Qué configuración es adecuada?", ["RAID 0 con striping en los cuatro discos", "RAID 1 en espejo en dos pares", "JBOD con spanning (concatenación)", "RAID 5 con un disco como paridad"], "JBOD con spanning une los discos uno tras otro, así que se usa la capacidad completa de cada disco aunque los tamaños sean distintos. RAID 0 es tentador porque tampoco tiene redundancia, pero limita cada miembro al tamaño del disco más pequeño.", ["RAID 0 limita cada miembro al tamaño del disco más pequeño y desperdicia capacidad en los discos más grandes.", "El espejo reduce la capacidad a la mitad y los pares de distinto tamaño desperdician aún más; agrega una redundancia que no se pidió.", null, "RAID 5 cede la capacidad de un disco a la paridad y está limitado por el disco más pequeño."]],
  "x7": ["Varios departamentos necesitan carpetas compartidas accesibles por SMB y NFS, y el propio dispositivo de almacenamiento debe gestionar el sistema de archivos. ¿Qué tipo de almacenamiento es adecuado?", ["Un target iSCSI que presenta LUN de bloque", "Un appliance NAS", "Un arreglo SAN Fibre Channel", "Un gabinete DAS conectado por SAS"], "Un NAS administra el sistema de archivos y sirve archivos por SMB y NFS a muchos clientes. Un target iSCSI es tentador porque también usa Ethernet, pero sirve bloques crudos y deja que cada servidor gestione su propio sistema de archivos.", ["Un target iSCSI sirve bloques crudos; cada servidor gestionaría su propio sistema de archivos, no el dispositivo.", null, "Una SAN Fibre Channel también presenta almacenamiento de bloque y no sirve recursos compartidos SMB o NFS por sí misma.", "DAS se conecta a un solo servidor por SAS y no comparte archivos por la red por sí mismo."]],
  "x8": ["Una empresa quiere transportar tráfico de almacenamiento Fibre Channel sobre su red de data center de 10 GbE existente usando adaptadores convergentes, sin encapsularlo en TCP/IP. ¿Qué protocolo es adecuado?", ["iSCSI sobre una VLAN de almacenamiento dedicada", "Túneles FCIP entre los switches", "SMB Direct sobre NIC con soporte RDMA", "FCoE"], "FCoE encapsula tramas Fibre Channel directamente en tramas Ethernet sobre una red sin pérdidas, sin capa IP. FCIP es tentador porque también transporta tráfico FC, pero lo tuneliza sobre TCP/IP, normalmente para unir SAN distantes.", ["iSCSI encapsula comandos SCSI en TCP/IP, que es justamente la encapsulación IP que el enunciado descarta.", "FCIP tuneliza Fibre Channel sobre TCP/IP, normalmente para unir SAN distantes, así que sigue usando IP.", "SMB Direct es un protocolo para compartir archivos sobre RDMA, no una forma de transportar tramas Fibre Channel.", null]],
  "x9": ["Una sala de servidores tiene 20 servidores sin funciones de BMC licenciadas. Los administradores quieren ver y controlar la consola de cualquier servidor desde sus escritorios, incluidas las pantallas de configuración del firmware. ¿Qué es adecuado?", ["Un switch KVM IP conectado a los puertos de video y USB de cada servidor", "Un carrito de consola (crash cart) guardado en la sala de servidores", "Remote Desktop habilitado en cada servidor", "Acceso SSH a través de un jump host endurecido"], "Un KVM IP captura las señales reales de video y teclado, así que muestra las pantallas de BIOS/UEFI de forma remota. RDP y SSH son tentadores, pero necesitan un sistema operativo en ejecución y no pueden mostrar el POST ni la configuración del firmware; un crash cart requiere estar presente físicamente.", [null, "Un crash cart requiere que alguien esté físicamente en la sala de servidores, lo que no permite trabajar desde el escritorio.", "Remote Desktop requiere un Windows en ejecución y no puede mostrar el POST ni las pantallas de configuración del firmware.", "SSH también depende de un sistema operativo y una pila de red en ejecución, así que no puede mostrar las pantallas del firmware."]],
  "x10": ["Un administrador quiere que BitLocker en el volumen del sistema operativo de un servidor se desbloquee automáticamente al arrancar solo si los componentes iniciales de arranque no fueron alterados. ¿Qué componente de hardware proporciona esto?", ["Un BMC con soporte de medios virtuales", "Un disco SAS autocifrado", "Un Trusted Platform Module (TPM)", "El Compatibility Support Module de UEFI"], "Un TPM guarda la llave y la libera solo cuando las mediciones de arranque coinciden con los valores esperados, lo que permite un desbloqueo automático pero sensible a alteraciones. Un disco autocifrado es tentador, pero cifra en hardware sin medir la cadena de arranque.", ["Los medios virtuales de un BMC montan imágenes ISO de forma remota; no miden los componentes de arranque ni liberan llaves.", "Un disco autocifrado cifra en hardware, pero no mide la cadena de arranque para detectar alteraciones.", null, "CSM habilita el arranque BIOS heredado y deshabilita Secure Boot; no ofrece almacenamiento de llaves ni mediciones."]],
  "x11": ["Un servidor con 24 ranuras DIMM se llenará por completo con módulos de alta capacidad. El fabricante exige módulos con un chip registro que haga de buffer para las señales de comando y dirección, para que más DIMM puedan compartir un canal. ¿Qué tipo es este?", ["UDIMM ECC unbuffered con tiempos estándar", "DIMM registrados (RDIMM)", "SO-DIMM", "DIMM de escritorio sin ECC"], "Los DIMM registrados agregan un registro que hace de buffer para las líneas de comando y dirección, reduciendo la carga eléctrica para que los servidores usen muchos módulos por canal. Los DIMM ECC unbuffered son tentadores porque también corrigen errores, pero no tienen el registro y soportan menos módulos por canal.", ["Los DIMM ECC unbuffered corrigen errores, pero no tienen el registro, así que menos módulos pueden compartir un canal.", null, "Los SO-DIMM son módulos pequeños para laptops y sistemas compactos, no para tarjetas de servidor de alta densidad.", "Los DIMM de escritorio sin ECC no tienen ni corrección de errores ni el registro del que dependen los servidores."]],
  "x12": ["¿Qué sistema de archivos de Windows Server está diseñado para la resiliencia, usa checksums e integrity streams y se usa comúnmente para volúmenes de Hyper-V y Storage Spaces?", ["NTFS", "exFAT", "FAT32", "ReFS"], "ReFS (Resilient File System) agrega checksums, integrity streams y reparación de corrupción con Storage Spaces. NTFS es tentador por ser el sistema de archivos predeterminado de Windows, pero no ofrece la verificación de integridad de ReFS.", ["NTFS es el sistema de archivos predeterminado de Windows, pero no tiene los integrity streams ni la reparación automática de ReFS.", "exFAT es un sistema de archivos ligero para medios removibles, sin verificación de integridad.", "FAT32 es un sistema de archivos heredado con un límite pequeño de tamaño de archivo y sin funciones de resiliencia.", null]],
  "x13": ["Un administrador formatea un LUN compartido para que varios hosts VMware ESXi puedan almacenar y ejecutar VM desde él al mismo tiempo. ¿Qué sistema de archivos se usa?", ["VMFS", "ext4", "XFS", "ReFS"], "VMFS es el sistema de archivos en clúster de VMware, que permite que varios hosts ESXi accedan al mismo datastore de forma simultánea. XFS es tentador porque maneja bien archivos grandes, pero es un sistema de archivos de Linux y no es lo que usa ESXi para datastores de bloque compartidos.", [null, "ext4 es un sistema de archivos de Linux y no es un datastore en clúster que compartan los hosts ESXi.", "XFS maneja bien archivos grandes en Linux, pero ESXi no lo usa para datastores compartidos.", "ReFS es un sistema de archivos de Windows usado con Hyper-V, no para datastores de VMware ESXi."]],
  "x14": ["Un administrador instala Windows Server en 15 hosts físicos desde medios de instalación y quiere que cada instalación elija las mismas particiones, configuración regional y ajustes de administrador sin preguntas. ¿Qué debe usar?", ["Una herramienta de conversión P2V", "Una plantilla de VM en el hipervisor", "Un archivo de respuestas unattend.xml", "Una reserva DHCP para cada host"], "Un archivo de respuestas proporciona las respuestas a las preguntas del instalador para que cada instalación se ejecute desatendida e idéntica. Una plantilla de VM es tentadora para compilaciones estándar, pero estos son hosts físicos instalados desde medios, no VM.", ["P2V convierte un servidor físico existente en una VM; no automatiza instalaciones nuevas.", "Una plantilla de VM solo ayuda a desplegar VM en un hipervisor, pero estos son hosts físicos instalados desde medios.", null, "Una reserva DHCP fija una dirección IP; no responde ninguna pregunta del instalador."]],
  "x15": ["Un administrador clonará una VM de Windows Server ya configurada para crear cinco nuevos miembros del dominio. ¿Qué se debe hacer con la VM de origen antes de capturarla como imagen?", ["Unirla primero al dominio para que los clones hereden la membresía", "Generalizarla con Sysprep", "Tomar un snapshot y luego eliminar el disco padre", "Asignarle una IP estática para que cada clon la conserve"], "Sysprep generaliza la imagen y elimina la identidad específica de la máquina, para que cada clon obtenga una identidad única. Unirla primero al dominio es tentador, pero todos los clones compartirían la misma cuenta de equipo e identidad, lo que causa conflictos.", ["Unirla primero daría a todos los clones la misma identidad y cuenta de equipo, lo que causa conflictos en el dominio.", null, "Eliminar un disco padre rompe la cadena de snapshots y no hace única la imagen.", "Que todos los clones conserven la misma IP estática causaría conflictos de direcciones en la red."]],
  "x16": ["La interfaz de red de un servidor muestra una dirección IPv6 que empieza con fe80:: y ninguna otra dirección IPv6. ¿Qué indica esto?", ["El servidor obtuvo una dirección enrutable globalmente mediante SLAAC", "La interfaz se unió a un grupo multicast IPv6 para routers", "La interfaz solo usa la dirección de loopback IPv6", "Solo existe una dirección link-local, utilizable en el segmento local"], "Las direcciones en fe80::/10 son link-local; cada interfaz IPv6 crea una automáticamente y no se pueden enrutar. Una dirección global por SLAAC es tentadora, pero empezaría con un prefijo global, no con fe80.", ["Una dirección unicast global por SLAAC empezaría con un prefijo global enrutable, no con fe80.", "Las direcciones multicast IPv6 empiezan con ff, no con fe80.", "La dirección de loopback IPv6 es ::1, no una dirección fe80::.", null]],
  "x17": ["Un servidor nuevo ofrecerá LDAP sobre TLS (LDAPS) para consultas al directorio. ¿Qué puerto TCP entrante debe permitir su firewall de host?", ["636", "389", "3389", "443"], "LDAPS usa TCP 636 por defecto. El puerto 389 es la opción tentadora, pero ese es LDAP estándar, que no está cifrado a menos que se actualice con StartTLS.", [null, "El puerto 389 es LDAP simple, que no está cifrado a menos que se actualice con StartTLS.", "El puerto 3389 es Remote Desktop Protocol, no un servicio de directorio.", "El puerto 443 es HTTPS para tráfico web, no LDAPS."]],
  "x18": ["Un servidor Linux une dos NIC en modo 802.3ad (LACP). El bond reporta que no hay partner LACP y el rendimiento es bajo. Los dos puertos del switch son puertos access simples. ¿Qué falta?", ["Un segundo gateway predeterminado en la interfaz del bond", "Jumbo frames habilitados en ambas NIC físicas", "Un port channel LACP correspondiente en los puertos del switch", "Una dirección IP separada configurada en cada NIC miembro"], "LACP es un protocolo negociado, así que el switch debe tener los dos puertos en un port channel LACP correspondiente. Una IP separada por miembro es tentadora, pero el bonding coloca la IP en el propio bond, y eso no crearía un partner LACP.", ["Un bond usa un solo gateway predeterminado como cualquier interfaz; un segundo gateway no crea un partner LACP.", "Los jumbo frames cambian el tamaño de trama, pero no tienen nada que ver con la negociación LACP.", null, "En el bonding, la dirección IP está en la interfaz del bond, no en cada NIC miembro."]],
  "x19": ["Una tienda en línea guarda los carritos de compra en la memoria local de cada servidor web. Detrás de un balanceador de carga round robin, los usuarios pierden sus carritos al azar. ¿Qué configuración del balanceador soluciona esto sin cambiar la aplicación?", ["Cambiar el pool al algoritmo least connections", "Habilitar la persistencia de sesión (sticky sessions)", "Configurar failover activo-pasivo", "Ejecutar health checks cada cinco segundos"], "La persistencia de sesión envía a cada usuario de vuelta al mismo servidor, donde el carrito vive en memoria. Least connections es tentador porque balancea mejor, pero igual mueve a los usuarios entre servidores y pierden sus carritos.", ["Least connections sigue enviando las solicitudes de un usuario a distintos servidores, así que los carritos se siguen perdiendo.", null, "El failover activo-pasivo usa un solo servidor a la vez y cambia el diseño en lugar de resolver las sesiones.", "Los health checks retiran los servidores caídos, pero no mantienen al usuario en el servidor que tiene su carrito."]],
  "x20": ["En un clúster activo-pasivo, el nodo principal falló y los servicios pasaron al secundario. El principal ya está reparado. ¿Cómo se llama volver a mover los servicios a él?", ["Failover", "Heartbeat", "Split-brain", "Failback"], "Failback devuelve los servicios al principal original después de restaurarlo. Failover es tentador, pero ese término describe el movimiento original lejos del nodo fallado.", ["Failover es el movimiento lejos del principal fallado, no el regreso a él.", "El heartbeat es la señal que usan los nodos para verificar la salud del otro.", "Split-brain es una falla en la que ambos nodos creen estar activos, no un movimiento planificado.", null]],
  "x21": ["¿Qué afirmación distingue MEJOR la tolerancia a fallas de la alta disponibilidad?", ["La tolerancia a fallas continúa sin interrupción cuando falla una parte; HA puede permitir una breve caída durante el failover", "La tolerancia a fallas depende de agrupar servidores completos en clúster, mientras que HA depende solo de partes redundantes dentro de un servidor", "La tolerancia a fallas protege solo contra la pérdida de datos, mientras que HA protege contra todo tipo de inactividad", "La tolerancia a fallas es una función solo de software, mientras que HA siempre requiere hardware redundante especializado"], "Un diseño tolerante a fallas sigue funcionando ante la falla de un componente sin interrupción, mientras que HA minimiza la inactividad pero puede tener una pausa breve durante el failover. La respuesta del clúster es tentadora, pero está invertida: el clúster es un método típico de HA.", [null, "Esto está invertido: agrupar servidores completos en clúster es un método típico de HA, y las partes redundantes apoyan la tolerancia a fallas.", "La tolerancia a fallas trata de seguir operando ante la falla de un componente, no solo de evitar la pérdida de datos.", "La tolerancia a fallas normalmente se logra con hardware redundante, así que decir que es solo de software es incorrecto."]],
  "x22": ["Una VM de base de datos sensible a la latencia se vuelve lenta en horas pico. Las CPU del host están completamente ocupadas y la VM muestra un CPU ready time alto. ¿Cuál es la MEJOR solución?", ["Agregar más vCPU a la VM para que haga más trabajo en paralelo", "Aumentar la memoria asignada a la VM", "Reducir la sobreasignación de CPU en el host o mover la VM a un host menos ocupado", "Convertir el disco virtual de la VM de thin a thick provisioning"], "Un ready time alto significa que la VM está esperando CPU física, así que el host está sobreasignado; liberar CPU o mover la VM lo resuelve. Agregar vCPU es tentador, pero en un host ocupado dificulta la planificación y normalmente aumenta el ready time.", ["Más vCPU hacen que la VM sea más difícil de planificar en un host ocupado y normalmente aumentan aún más el ready time.", "El síntoma es el CPU ready time, que apunta a contención de CPU, no a falta de memoria.", null, "El tipo de aprovisionamiento del disco afecta la asignación de almacenamiento, no el retraso de planificación de CPU que se observa aquí."]],
  "x23": ["En un host Hyper-V, un grupo de VM de prueba debe comunicarse entre sí, pero nunca debe llegar a la red física ni al propio host. ¿Qué tipo de switch virtual es adecuado?", ["External", "Private", "Internal", "External con etiquetado de VLAN"], "Un switch virtual privado conecta solo las VM que están en él, sin acceso al host ni a la red física. Un switch interno es tentador, pero también conecta el sistema operativo del host con las VM.", ["Un switch externo conecta las VM a la red física, lo que el enunciado prohíbe.", null, "Un switch interno también conecta el sistema operativo del host con las VM, lo que el enunciado prohíbe.", "Agregar etiquetado de VLAN a un switch externo igual deja las VM en la red física."]],
  "x24": ["Un administrador debe sacar las VM en ejecución de un host para darle mantenimiento al hardware sin tiempo de inactividad. Ambos hosts usan el mismo almacenamiento compartido. ¿Qué debe usar?", ["Migración en frío después de apagar cada VM", "Una conversión P2V de cada VM", "Restaurar cada VM desde el respaldo de anoche", "Migración en vivo (live migration)"], "La migración en vivo (como vMotion o Hyper-V Live Migration) mueve la memoria y el estado de una VM en ejecución a otro host sin inactividad perceptible. La migración en frío es tentadora porque también mueve VM, pero requiere apagarlas.", ["La migración en frío requiere apagar cada VM, lo que causa la inactividad que el administrador debe evitar.", "P2V convierte servidores físicos en VM; estas ya son VM.", "Restaurar desde un respaldo causa inactividad y pierde los cambios hechos desde anoche.", null]],
  "x25": ["Los desarrolladores quieren desplegar código web sin parchear sistemas operativos ni instalar runtimes; el proveedor administra la plataforma subyacente. ¿Qué modelo de servicio de nube es adecuado?", ["PaaS", "IaaS", "SaaS", "Colocation en una nube privada"], "En PaaS el proveedor administra el sistema operativo y el runtime, y los clientes despliegan su propio código. IaaS es tentador, pero ahí el cliente sigue administrando y parcheando el sistema operativo.", [null, "Con IaaS el cliente sigue instalando, parcheando y administrando el sistema operativo y el runtime.", "SaaS entrega una aplicación terminada; los desarrolladores no pueden desplegar su propio código en ella.", "Colocation significa alojar su propio hardware en las instalaciones de otro, así que usted sigue administrando todo."]],
  "x26": ["Una empresa mantiene su base de datos de clientes on-premises por cumplimiento normativo, pero ejecuta su sitio web público en un proveedor de nube, con ambos entornos conectados. ¿Qué modelo de despliegue es este?", ["Nube pública", "Nube privada", "Nube híbrida", "Nube comunitaria"], "La nube híbrida combina recursos on-premises o privados con servicios de nube pública que funcionan juntos. La nube pública es tentadora porque el sitio web está ahí, pero la base de datos se queda on-premises, lo que hace híbrido todo el entorno.", ["Solo el sitio web está en la nube pública; la base de datos se queda on-premises, así que no es puramente pública.", "Una nube privada es infraestructura dedicada, pero aquí un proveedor público aloja parte del entorno.", null, "Una nube comunitaria es compartida por organizaciones con necesidades comunes, lo que no se describe aquí."]],
  "x27": ["Un script de Bash debe imprimir una advertencia cuando la variable USED contiene un número mayor que 90. ¿Qué prueba es correcta?", ["if ($USED -gt 90) {", "if [ \"$USED\" -gt 90 ]; then", "if [ \"$USED\" > 90 ]; then", "if [ \"$USED\" -greater 90 ]; then"], "En Bash, el comando test usa -gt para «mayor que» numérico dentro de [ ], seguido de then. Usar > es tentador, pero dentro de [ ] se interpreta como redirección de salida y crea un archivo llamado 90 en lugar de comparar.", ["Esta es sintaxis de PowerShell con paréntesis y llaves; Bash no la interpretaría como una condición.", null, "Dentro de [ ], > se interpreta como redirección de salida y crea un archivo llamado 90 en lugar de comparar.", "-greater no es un operador de test válido; Bash usa -gt para «mayor que» numérico."]],
  "x28": ["Un administrador de Windows necesita que un script de PowerShell se ejecute cada día hábil a las 6:00 AM con una cuenta de servicio, haya o no alguien con sesión iniciada. ¿Qué debe usar?", ["Una entrada de cron en el servidor", "Un script de inicio de sesión de Group Policy", "Un servicio de Windows configurado con inicio Automatic", "Task Scheduler"], "Task Scheduler ejecuta scripts según un horario con una cuenta elegida sin que nadie haya iniciado sesión. Un script de inicio de sesión es tentador, pero solo se ejecuta cuando un usuario inicia sesión, no a una hora fija.", ["cron es el programador de Linux y no forma parte de Windows Server.", "Un script de inicio de sesión solo se ejecuta cuando un usuario inicia sesión, no a las 6:00 AM sin nadie conectado.", "Un servicio se ejecuta de forma continua, no según un horario de días hábiles, y un script no se escribe como servicio.", null]],
  "x29": ["Un proveedor cobra una tarifa anual que incluye actualizaciones y soporte, y el derecho a usar el software termina cuando se dejan de hacer los pagos. ¿Qué modelo de licenciamiento es este?", ["Suscripción", "Perpetua por dispositivo", "Licencia de sitio", "Por socket"], "El licenciamiento por suscripción otorga el uso mientras se pague la tarifa recurrente, normalmente con actualizaciones incluidas. Una licencia perpetua es tentadora porque también puede tener mantenimiento anual, pero su derecho de uso no termina cuando se dejan de hacer los pagos.", [null, "Una licencia perpetua permite seguir usando el software aunque deje de pagar el mantenimiento.", "Una licencia de sitio cubre todo el uso en una ubicación; describe el alcance, no un derecho de uso recurrente.", "El licenciamiento por socket cuenta procesadores; no dice nada sobre el fin del uso cuando se dejan de hacer los pagos."]],
  "x30": ["Cada noche se copian respaldos de un servidor de sucursal a la oficina central a través de internet. ¿Qué control protege los datos mientras cruzan la red?", ["Cifrado de disco completo en los volúmenes del servidor de la sucursal", "Guardar los medios de respaldo en un gabinete con llave", "Un túnel cifrado como una VPN o TLS", "Comprimir los archivos de respaldo antes de enviarlos"], "El cifrado en tránsito, como una VPN o TLS, protege los datos mientras viajan por redes no confiables. El cifrado de disco completo es tentador, pero protege los datos en reposo en el disco, no mientras se envían.", ["El cifrado de disco completo protege los datos en reposo en el servidor, no mientras cruzan internet.", "Un gabinete con llave es seguridad física para los medios y no protege el tráfico de red.", null, "La compresión reduce el tamaño de los archivos, pero no oculta su contenido a quien los intercepte."]],
  "x31": ["Un data center quiere un sistema de supresión de incendios que no empape los equipos con agua y no deje residuos en la electrónica. ¿Qué opción es la MEJOR?", ["Un sistema de rociadores de tubería húmeda (wet-pipe)", "Un sistema de supresión por agente limpio gaseoso", "Extintores de químico seco montados en cada rack", "Un sistema de rociadores de diluvio (deluge)"], "Los sistemas de gas de agente limpio suprimen el fuego sin agua y no dejan residuos, lo que protege la electrónica. Los extintores de químico seco son tentadores porque evitan el agua, pero el polvo es corrosivo y deja residuos en los equipos.", ["Los rociadores de tubería húmeda descargan agua, que daña la electrónica.", null, "El polvo químico seco es corrosivo y deja residuos que dañan la electrónica.", "Un sistema de diluvio inunda el área con agua, lo contrario de lo que se busca."]],
  "x32": ["La cuenta de servicio de una aplicación se hizo Domain Admin porque era más fácil. ¿Qué cambio reduce MEJOR el riesgo manteniendo la aplicación funcionando?", ["Renombrar la cuenta para que los atacantes no puedan adivinarla", "Configurar su contraseña para que nunca expire y evitar caídas", "Agregarla en su lugar al grupo local Administrators de cada servidor", "Otorgar solo los derechos que necesita la aplicación y denegar el inicio de sesión interactivo"], "El mínimo privilegio para cuentas de servicio significa dar solo los derechos que necesita la aplicación y bloquear el uso interactivo. Ser administrador local en cada servidor es tentador como un paso hacia abajo, pero sigue otorgando un control amplio sobre todo el entorno.", ["Renombrar la cuenta es solo oscuridad; conserva todos los derechos de administrador del dominio.", "Una contraseña que nunca expira aumenta el riesgo y no reduce los privilegios excesivos.", "Ser administrador local en cada servidor sigue otorgando un control amplio sobre el entorno.", null]],
  "x33": ["Los logs muestran miles de intentos de adivinar la contraseña de una sola cuenta de administrador. ¿Qué política limita MÁS directamente este ataque?", ["Bloqueo de cuenta después de varios intentos fallidos", "Un historial de 24 contraseñas recordadas", "Una antigüedad mínima de contraseña de un día", "Deshabilitar la cuenta Guest integrada"], "El bloqueo de cuenta detiene o frena los intentos repetidos bloqueando la cuenta después de cierto número de fallas. El historial de contraseñas es tentador porque es una política de contraseñas, pero solo impide reutilizar contraseñas antiguas y no hace nada contra el adivinado.", [null, "El historial de contraseñas solo impide reutilizar contraseñas antiguas; no hace nada para detener el adivinado.", "La antigüedad mínima de contraseña impide cambios rápidos de contraseña y no limita el adivinado.", "La cuenta Guest no es la que está siendo atacada, así que deshabilitarla no detiene estos intentos."]],
  "x34": ["¿Qué método de inicio de sesión es un ejemplo de autenticación multifactor?", ["Una contraseña más la respuesta a una pregunta de seguridad", "Un PIN más una contraseña", "Una contraseña más un código de una aplicación autenticadora", "Un escaneo de huella digital más un escaneo de palma"], "Una contraseña (algo que sabe) más un código de aplicación (algo que tiene) combina dos tipos de factor diferentes. La opción de huella y palma es tentadora porque usa dos verificaciones, pero ambas son biométricas, el mismo tipo de factor.", ["Una pregunta de seguridad es otra cosa que usted sabe, el mismo factor que una contraseña.", "Un PIN y una contraseña son ambos algo que usted sabe, así que es de un solo factor.", null, "Los escaneos de huella y de palma son ambos biométricos, el mismo tipo de factor."]],
  "x35": ["Los usuarios se quejan de tener que iniciar sesión por separado en la intranet, el sistema de tickets y el correo. ¿Qué solución permite que una sola autenticación dé acceso a los tres?", ["MFA en cada aplicación", "Single sign-on (SSO)", "Una cuenta genérica compartida por departamento", "Una política de complejidad de contraseñas más estricta"], "SSO permite que los usuarios se autentiquen una vez y luego accedan a varias aplicaciones que confían en esa autenticación. MFA es tentador porque mejora la autenticación, pero agrega factores en lugar de reducir el número de inicios de sesión.", ["MFA agrega factores a cada inicio de sesión en lugar de reducir cuántas veces inician sesión los usuarios.", null, "Las cuentas compartidas rompen la trazabilidad y son un riesgo de seguridad; no son SSO.", "Reglas de complejidad más estrictas hacen más difícil iniciar sesión y no unifican los inicios de sesión."]],
  "x36": ["Unos archivos confidenciales desaparecieron de un recurso compartido y nadie sabe quién los eliminó. ¿Qué debió habilitarse de antemano para responder esa pregunta?", ["Volume shadow copies en el recurso compartido", "Permisos de solo lectura en el recurso compartido para todos", "BitLocker en el volumen de datos", "Auditoría de acceso a objetos en la carpeta"], "La auditoría de acceso a objetos registra qué cuenta leyó, cambió o eliminó archivos. Las shadow copies son tentadoras porque ayudan a recuperar los archivos, pero no registran quién los eliminó.", ["Las shadow copies pueden restaurar los archivos, pero no registran qué cuenta los eliminó.", "Los permisos de solo lectura podrían haber evitado la eliminación, pero no dejan registro de quién hizo qué.", "BitLocker protege los datos en reposo contra robo y no registra eliminaciones de archivos.", null]],
  "x37": ["Un ransomware en la PC de un usuario se propagó a todos los servidores porque todos los sistemas estaban en una sola red plana. ¿Qué mitigación limita MEJOR esta propagación en el futuro?", ["Segmentar la red con reglas de firewall entre las VLAN de usuarios y de servidores", "Aumentar la frecuencia de respaldo de cada noche a cada hora", "Agregar un segundo controlador de dominio en el sitio", "Habilitar NIC teaming en todos los servidores"], "La segmentación limita a qué sistemas pueden llegar los clientes infectados, conteniendo el movimiento lateral. Respaldar con más frecuencia es tentador porque ayuda a la recuperación, pero no hace nada para detener la propagación del ransomware.", [null, "Respaldar con más frecuencia ayuda a recuperarse, pero no hace nada para detener la propagación del ransomware.", "Un segundo controlador de dominio agrega redundancia al directorio, pero no bloquea el movimiento lateral.", "NIC teaming proporciona redundancia de enlaces y no tiene efecto sobre la propagación de malware."]],
  "x38": ["Al endurecer (hardening) un servidor, ¿cómo debe manejar su firewall de host el tráfico entrante?", ["Permitir todo por defecto y bloquear los puertos maliciosos conocidos", "Permitir todo el tráfico que venga de la red interna", "Denegar por defecto y permitir solo los puertos que necesitan sus roles", "Apagarlo porque el firewall perimetral ya filtra el tráfico"], "Una política de entrada de denegación por defecto con solo los puertos necesarios abiertos reduce la superficie de ataque. Confiar en todo el tráfico interno es tentador, pero las amenazas a menudo vienen de hosts internos comprometidos, así que el tráfico interno también necesita filtrarse.", ["Permitir por defecto deja expuesto cada servicio innecesario, lo contrario del hardening.", "Confiar en todo el tráfico interno ignora los hosts internos comprometidos, una ruta de ataque común.", null, "Depender solo del perímetro deja el servidor expuesto a cualquier cosa que ya esté dentro."]],
  "x39": ["Una empresa quiere reutilizar en su laboratorio de pruebas los discos duros de servidores retirados en lugar de destruirlos, pero sanitizando los datos anteriores. ¿Qué método es adecuado?", ["Desmagnetizar cada disco", "Sobrescribir cada sector con una herramienta de borrado verificado", "Triturar los discos y reciclar los platos", "Hacer un formateo rápido de cada disco"], "Una sobrescritura verificada elimina los datos y deja el disco utilizable. La desmagnetización es tentadora porque sanitiza medios magnéticos, pero también destruye la información servo del disco, así que no puede reutilizarse.", ["La desmagnetización también borra las pistas servo del disco y lo deja inutilizable.", null, "La trituración destruye los discos, pero el objetivo es reutilizarlos.", "Un formateo rápido solo reconstruye las estructuras del sistema de archivos y deja los datos anteriores recuperables."]],
  "x40": ["La ventana de respaldo es demasiado corta para enviar cada semana un respaldo completo por la red. El servidor de respaldo puede construir un completo nuevo a partir del último completo más los incrementales que ya tiene. ¿Qué es esto?", ["Un respaldo diferencial tomado cada noche", "Un snapshot de almacenamiento", "Un respaldo espejo", "Un respaldo completo sintético"], "Un completo sintético se ensambla en el servidor de respaldo a partir de los respaldos completos e incrementales existentes, sin volver a leer el origen. Un diferencial es tentador, pero sigue copiando los datos cambiados desde el origen y no es un completo nuevo.", ["Un diferencial copia los datos cambiados desde el origen; no es un respaldo completo nuevo construido en el servidor.", "Un snapshot de almacenamiento es una imagen de un punto en el tiempo en el mismo almacenamiento, no un completo construido a partir de incrementales.", "Un respaldo espejo copia el origen tal cual y sigue leyendo todo desde el origen.", null]],
  "x41": ["Un administrador sostiene que los snapshots de VM guardados en el mismo datastore hacen innecesarios los respaldos separados. ¿Por qué está equivocado?", ["Los snapshots dependen de los discos originales, así que perder ese almacenamiento hace perder ambos", "Los snapshots solo se pueden tomar con la VM completamente apagada", "Los snapshots solo registran el estado de la memoria y nunca capturan datos del disco", "El hipervisor siempre elimina automáticamente los snapshots después de un día"], "Un snapshot es un delta que depende del disco base en el mismo almacenamiento, así que una falla del datastore destruye ambos. La respuesta de solo memoria es tentadora, pero los snapshots sí capturan el estado del disco; el problema es que no son copias independientes.", [null, "Los snapshots se pueden tomar con las VM en ejecución; ese es uno de sus usos principales.", "Los snapshots sí capturan el estado del disco (y opcionalmente la memoria); el problema es su dependencia de los discos base.", "Los hipervisores no eliminan los snapshots automáticamente después de un día; permanecen hasta que se eliminan."]],
  "x42": ["Una empresa puede tolerar unos días de inactividad después de un desastre. Quiere hardware y enlaces de red listos en el sitio de recuperación, pero restaurará los datos actuales desde respaldos, con costos moderados. ¿Qué tipo de sitio es adecuado?", ["Sitio caliente (hot site)", "Sitio frío (cold site)", "Sitio tibio (warm site)", "Acuerdo recíproco sin equipo definido"], "Un warm site tiene equipos y conectividad instalados, pero necesita restaurar los datos, lo que permite recuperarse en horas o días a un costo moderado. Un cold site es tentador porque es más barato, pero no tiene hardware listo y tarda más en ponerse en marcha.", ["Un hot site mantiene datos actualizados y puede tomar el control en minutos, a un costo mucho mayor de lo necesario.", "Un cold site tiene espacio y energía, pero no hardware listo, así que la recuperación tarda más de lo deseado.", null, "Un acuerdo recíproco sin equipo definido no garantiza el hardware listo que exige el enunciado."]],
  "x43": ["Un modelo de servidor falla en promedio una vez cada 50,000 horas, y cada reparación toma unas 4 horas. ¿Qué métrica son las 4 horas?", ["MTBF", "MTTR", "RTO", "RPO"], "El tiempo medio de reparación (MTTR) es el tiempo promedio para restaurar un componente fallado. RTO es tentador, pero es una meta de negocio de qué tan rápido debe recuperarse un servicio, no un tiempo promedio de reparación medido.", ["MTBF es el tiempo promedio entre fallas, en este caso las 50,000 horas.", null, "RTO es una meta de negocio para el tiempo de recuperación, no un tiempo promedio de reparación medido.", "RPO es la pérdida de datos máxima aceptable medida en tiempo, sin relación con la duración de la reparación."]],
  "x44": ["Un técnico cree que una actualización fallida del driver de la NIC causó la caída de un servidor. Según la metodología de troubleshooting de CompTIA, ¿qué debe hacer el técnico a continuación?", ["Probar la teoría para determinar la causa", "Implementar la solución reinstalando el driver", "Documentar los hallazgos y cerrar el ticket", "Verificar la funcionalidad completa del sistema"], "Después de establecer una teoría de la causa probable, el siguiente paso es probarla para confirmar la causa. Implementar la solución es tentador, pero actuar antes de confirmar la teoría arriesga cambiar lo que no es.", [null, "Implementar una solución antes de confirmar la teoría arriesga cambiar lo que no es.", "La documentación es el último paso, después de implementar y verificar la solución.", "La verificación viene después de implementar una solución, lo cual todavía no ha ocurrido."]],
  "x45": ["Después de reemplazar una controladora RAID fallada, el servidor arranca y el arreglo está en buen estado. Según la metodología de troubleshooting, ¿qué sigue?", ["Documentar los hallazgos y cerrar el ticket", "Establecer una nueva teoría de la causa probable", "Escalar el problema al fabricante del hardware", "Verificar la funcionalidad completa del sistema y aplicar medidas preventivas"], "Después de implementar la solución, el técnico verifica la funcionalidad completa y aplica medidas preventivas, y luego documenta. Documentar es tentador, pero es el último paso y va después de la verificación.", ["Documentar es el último paso y va después de verificar la funcionalidad completa.", "La solución funcionó, así que no hace falta formular una nueva teoría.", "El escalamiento es para cuando un problema no se puede resolver; este ya se resolvió.", null]],
  "x46": ["Un disco en una bahía hot-swap muestra un indicador ámbar de falla predictiva, pero el arreglo sigue en estado óptimo. ¿Cuál es la MEJOR acción?", ["Ignorarlo hasta que el arreglo aparezca como degradado", "Reemplazar el disco en una ventana planificada antes de que falle", "Reconstruir todo el arreglo desde cero con discos nuevos", "Volver a asentar el disco para borrar la advertencia"], "Una alerta de falla predictiva significa que es probable que el disco falle pronto, así que reemplazarlo de forma controlada evita operar en modo degradado. Volver a asentarlo es tentador como solución rápida, pero solo oculta la advertencia y la falla de fondo sigue ahí.", ["Esperar a que el arreglo se degrade significa operar sin redundancia cuando podría ocurrir una segunda falla.", null, "Reconstruir todo el arreglo es disruptivo e innecesario cuando solo un disco está marcado.", "Volver a asentar el disco solo borra el indicador temporalmente; la falla de fondo del disco sigue ahí."]],
  "x47": ["Después de que falló un ventilador en un servidor de 1U, los ventiladores restantes giran a máxima velocidad y el BMC registra advertencias de temperatura de CPU. ¿Qué debe hacer el administrador?", ["Subir los umbrales de temperatura del BMC para que se detengan las alertas", "Quitar los paneles ciegos cercanos para que entre más aire frío", "Reemplazar el módulo de ventilador fallado y revisar la ruta del flujo de aire", "Subir la velocidad de reloj de la CPU para que las tareas terminen más rápido"], "Reemplazar el ventilador fallado restablece el enfriamiento diseñado, y revisar el flujo de aire detecta otras obstrucciones. Quitar los paneles ciegos es tentador, pero deja que el escape caliente recircule hacia el frente y empeora el enfriamiento.", ["Subir los umbrales oculta la advertencia y deja que los componentes funcionen más calientes hasta que fallen.", "Quitar los paneles ciegos deja que el escape caliente recircule hacia el frente, lo que empeora el enfriamiento.", null, "Las velocidades de reloj más altas generan más calor y empeoran un problema de sobrecalentamiento."]],
  "x48": ["Después de agregar memoria, un servidor falla el POST con un error de configuración de memoria. Los módulos nuevos son del mismo tipo que los existentes. ¿Cuál es la causa MÁS probable?", ["Los módulos no están instalados en el orden de ocupación de ranuras que exige el fabricante", "El sistema operativo no tiene drivers para la memoria nueva", "La caché de la controladora RAID es demasiado pequeña para la nueva RAM", "El UPS no puede suministrar suficiente energía para los módulos agregados"], "Los servidores requieren los DIMM en ranuras y patrones de canal específicos, y una colocación incorrecta causa errores de configuración en el POST. Los drivers del sistema operativo son tentadores, pero el POST ocurre antes de que cargue el sistema operativo, así que no pueden ser la causa.", [null, "El POST se ejecuta antes de que cargue cualquier sistema operativo, así que los drivers no pueden causar un error de memoria en el POST.", "La caché de la controladora RAID es independiente de la memoria del sistema y no tiene ningún papel en las verificaciones de memoria del POST.", "Una falta de energía causaría apagados o un encendido fallido, no un error de configuración de memoria."]],
  "x49": ["Durante la reconstrucción de un arreglo RAID 5 degradado hecho con discos grandes, la reconstrucción falla por errores de lectura en un disco sobreviviente y el arreglo se pierde. ¿Qué configuración habría sobrevivido mejor a esto?", ["RAID 0, porque se reconstruye más rápido", "JBOD, para que cada disco sea independiente", "RAID 5 con discos miembro adicionales", "RAID 6, que tolera una segunda falla durante la reconstrucción"], "La segunda paridad de RAID 6 permite que el arreglo sobreviva otro error de disco durante la reconstrucción. Agregar discos a RAID 5 es tentador, pero alarga las reconstrucciones y expone más discos a errores de lectura, tolerando igual una sola falla.", ["RAID 0 no tiene ninguna redundancia y se habría perdido con la primera falla de disco.", "JBOD no tiene redundancia, así que cualquier disco fallado pierde sus datos.", "Más miembros en RAID 5 alargan las reconstrucciones y siguen tolerando una sola falla.", null]],
  "x50": ["Los discos de un servidor fallado se movieron a un reemplazo idéntico. La controladora RAID los ve, pero muestra el arreglo como una configuración foránea (foreign). ¿Cómo debe acceder el administrador a los datos?", ["Inicializar el disco virtual para que sea utilizable", "Importar la configuración foránea en la utilidad de la controladora", "Ejecutar chkdsk sobre cada disco físico", "Borrar la configuración foránea y reconstruir el arreglo"], "Importar la configuración foránea adopta los metadatos RAID guardados en los discos y pone el arreglo en línea con los datos intactos. Borrar y reconstruir es tentador porque elimina la advertencia, pero descarta los metadatos y hace perder el arreglo.", ["Inicializar escribe un volumen nuevo vacío y destruye los datos existentes.", null, "chkdsk trabaja sobre sistemas de archivos a través del sistema operativo y no puede ver un arreglo que la controladora no ha puesto en línea.", "Borrar la configuración foránea descarta los metadatos RAID y hace perder el arreglo."]],
  "x51": ["El volumen de datos de un servidor Windows muestra corrupción del sistema de archivos después de un corte repentino de energía. ¿Qué herramienta debe usarse para repararlo?", ["sfc /scannow", "diskpart clean", "chkdsk /f sobre el volumen", "defrag con la opción /x"], "chkdsk /f verifica y repara las estructuras del sistema de archivos de un volumen. sfc /scannow es tentador, pero repara archivos protegidos del sistema Windows, no la corrupción del sistema de archivos de un volumen de datos.", ["sfc /scannow repara archivos protegidos del sistema Windows, no la corrupción del sistema de archivos de un volumen de datos.", "diskpart clean borra la tabla de particiones y destruye los datos.", null, "La desfragmentación reorganiza archivos y no repara la corrupción; puede empeorar el daño."]],
  "x52": ["Los usuarios dicen que un servidor de archivos está lento. Performance Monitor muestra una longitud de cola de disco constantemente alta, mientras que el uso de CPU y memoria es bajo. ¿Dónde está el cuello de botella?", ["El subsistema de almacenamiento", "Los procesadores", "La memoria física instalada", "El servidor DNS"], "Una cola de disco larga y sostenida con la CPU ociosa y memoria libre apunta a un almacenamiento que no puede seguir el ritmo de las solicitudes de E/S. La memoria es tentadora porque poca RAM puede causar paginación, pero aquí el uso de memoria es bajo, así que la paginación no es lo que carga los discos.", [null, "El uso de CPU es bajo, así que los procesadores no son lo que hace lento al servidor.", "El uso de memoria es bajo, así que no hay paginación intensa cargando los discos.", "El DNS afecta la resolución de nombres, no el rendimiento de disco de un servidor de archivos."]],
  "x53": ["El load average de un servidor Linux es muy alto. top muestra un script de respaldo atascado que usa 100% de CPU desde hace horas. ¿Qué debe hacer el administrador?", ["Reiniciar el servidor de inmediato", "Ejecutar fsck sobre el sistema de archivos raíz", "Hacer renice del proceso a -20", "Enviarle SIGTERM con kill, y usar kill -9 solo si lo ignora"], "Terminar el proceso descontrolado libera la CPU, y SIGTERM primero le permite limpiar antes de forzar la terminación. Hacer renice a -20 es tentador, pero -20 es la prioridad más alta, lo que haría que el proceso consuma aún más CPU.", ["Reiniciar interrumpe todos los servicios del servidor cuando solo hay que detener un proceso.", "fsck verifica sistemas de archivos; el problema es un proceso descontrolado, no corrupción del disco.", "Un valor nice de -20 da la prioridad más alta, lo que hace que el proceso consuma aún más CPU.", null]],
  "x54": ["Después de instalar un nuevo driver de almacenamiento, un servidor Windows se reinicia repetidamente antes de llegar a la pantalla de inicio de sesión. ¿Qué debe intentar PRIMERO el administrador?", ["Reinstalar Windows Server desde el medio de instalación", "Arrancar en Modo seguro o en recuperación y revertir el driver", "Reemplazar la tarjeta madre", "Actualizar el BIOS a la versión más reciente"], "El Modo seguro o el entorno de recuperación cargan un conjunto mínimo de drivers, lo que permite revertir el driver nuevo. Reinstalar el sistema operativo es tentador porque eliminaría la falla, pero es mucho más disruptivo que deshacer el único cambio reciente.", ["Reinstalar el sistema operativo es mucho más disruptivo que deshacer el único cambio reciente de driver.", null, "La falla empezó justo después de instalar un driver, lo que apunta al software, no a una tarjeta fallada.", "Una actualización de BIOS es un cambio no relacionado y agrega riesgo sin atender el driver nuevo."]],
  "x55": ["Un servidor con IP 10.1.20.15 y máscara 255.255.0.0 no puede llegar a hosts en 10.1.30.0/24. Otros servidores en 10.1.20.0/24 con máscara 255.255.255.0 sí pueden. ¿Cuál es la causa?", ["El gateway predeterminado del servidor está configurado como 10.1.20.1", "El servidor DNS no tiene registros para 10.1.30.0/24", "La máscara es demasiado amplia, así que el servidor trata a los hosts remotos como locales y omite el gateway", "La NIC del servidor funciona a 100 Mbps en lugar de 1 Gbps"], "Con una máscara /16 el servidor cree que 10.1.30.x está en su propio segmento, así que intenta ARP directamente en lugar de enviar al router. La respuesta del gateway es tentadora, pero los otros servidores que funcionan seguramente usan ese mismo gateway; la máscara incorrecta hace que nunca se use.", ["Un gateway 10.1.20.1 es normal para esta subred; con una máscara /16 el servidor nunca lo usa para 10.1.30.x.", "El problema es llegar a los hosts, no resolver nombres; los registros DNS no afectan el enrutamiento.", null, "La velocidad del enlace afecta el rendimiento, no si el servidor puede llegar a otra subred."]],
  "x56": ["Un administrador quiere confirmar que un servicio web de Linux está escuchando en el puerto TCP 8443 en el propio servidor. ¿Qué comando es adecuado?", ["ss -tlnp", "arp -a", "traceroute", "dig"], "ss -tlnp lista los sockets TCP en escucha con puertos numéricos y el proceso propietario. traceroute es tentador como herramienta de red, pero traza la ruta hacia un host remoto y no dice nada sobre los puertos locales en escucha.", [null, "arp -a muestra las asociaciones IP a MAC de los vecinos, no los puertos en escucha.", "traceroute traza la ruta hacia un host remoto y no dice nada sobre los sockets locales en escucha.", "dig consulta el DNS y no muestra qué puertos están en escucha."]],
  "x57": ["Las dos NIC de un servidor Windows se pusieron en un team switch-independent, y luego el equipo de redes configuró un grupo de agregación de enlaces (LAG) estático en los puertos correspondientes del switch. Ahora la conectividad es intermitente. ¿Cuál es la solución?", ["Asignar una dirección IP diferente a cada NIC del team", "Habilitar jumbo frames en la interfaz del team", "Reemplazar ambos cables de red", "Hacer que ambos lados coincidan: teaming estático/LACP con el LAG, o sin LAG"], "El modo de teaming debe coincidir con el switch: un team switch-independent debe conectarse a puertos normales, mientras que un LAG necesita un team switch-dependent (estático o LACP). Reemplazar los cables es tentador ante fallas intermitentes, pero aquí el síntoma sigue al cambio de configuración, no a una falla física.", ["Las NIC del team comparten una dirección en la interfaz del team; darle a cada una su propia IP no corrige el desajuste de modo.", "Los jumbo frames cambian el tamaño de trama y no resuelven el desajuste entre el teaming y el LAG.", "La falla empezó después del cambio de configuración, no por una falla física, así que es poco probable que sean los cables.", null]],
  "x58": ["Una nueva instancia de SQL Server funciona localmente, pero los clientes remotos agotan el tiempo de espera al conectarse a TCP 1433. El ping por nombre funciona y el servicio está en ejecución. ¿Cuál es la causa MÁS probable?", ["El DNS devuelve la dirección incorrecta del servidor", "El firewall del host está bloqueando TCP 1433 entrante", "Un desajuste de dúplex en el puerto del switch del servidor", "El certificado TLS del servidor venció recientemente"], "Los tiempos de espera agotados en un solo puerto mientras el ping y el servicio funcionan apuntan a un firewall que descarta ese puerto. El DNS es tentador, pero el ping por nombre ya resuelve y llega al servidor, así que la resolución de nombres funciona.", ["El ping por nombre ya resuelve y llega al servidor, así que el DNS funciona.", null, "Un desajuste de dúplex causa lentitud y errores, no un tiempo de espera limpio en un solo puerto mientras el ping funciona.", "Los errores de certificado TLS producen advertencias en el handshake, no tiempos de espera en la conexión TCP."]],
  "x59": ["Un usuario pertenece a Sales, que tiene NTFS Modify en una carpeta, y a Contractors, que tiene un Deny Write explícito en la misma carpeta. El usuario no puede guardar archivos ahí. ¿Por qué?", ["Los permisos del recurso compartido siempre prevalecen sobre los permisos NTFS de la carpeta", "Ganan los permisos del grupo agregado más recientemente", "Un deny explícito prevalece sobre el allow del otro grupo", "Modify no incluye la capacidad de crear archivos"], "NTFS combina los permisos de los grupos, pero un deny explícito tiene precedencia sobre un allow, así que el Deny Write bloquea el guardado. La idea de que los permisos del recurso compartido prevalecen sobre NTFS es tentadora, pero se aplica el más restrictivo de ambos, y no se mencionó ninguna restricción en el recurso compartido.", ["Se aplica el más restrictivo entre recurso compartido y NTFS, y no se menciona ningún permiso restrictivo en el recurso compartido.", "El orden de membresía en los grupos no importa; NTFS evalúa todas las entradas aplicables en conjunto.", null, "Modify incluye escribir y crear, así que permitiría guardar si no existiera el deny."]],
  "x60": ["Los logs muestran que una cuenta de servicio inicia sesión de forma interactiva a las 3 AM desde una estación de trabajo que nunca usa. ¿Qué debe hacer PRIMERO el administrador?", ["Deshabilitar la cuenta o restablecer sus credenciales, y luego investigar el origen", "Esperar una semana para reunir más evidencia antes de actuar", "Reconstruir todos los servidores del entorno desde cero", "Borrar los logs de seguridad para que no se llenen"], "La contención va primero: deshabilitar o restablecer las credenciales detiene el uso indebido mientras se investiga el origen. Esperar más evidencia es tentador, pero le da a un atacante más tiempo con una cuenta funcional.", [null, "Esperar le da a un atacante más tiempo con una cuenta funcional y arriesga más daño.", "Reconstruir todos los servidores es drástico antes de dimensionar el incidente; primero va la contención de la cuenta.", "Borrar los logs destruye la evidencia necesaria para investigar el incidente."]],
});
